insert into public.questions (id, subject, grade, category, difficulty, body, answer, distractors, explanation, image_url) values
  ('sci_1_b4_001', '理科', 1, '動物の分類', 2, '哺乳類について、体表はどれか。', '毛', array['うろこ', '皮膚', '羽毛'], '哺乳類の体表は毛でおおわれ、体を保護するとともに体温の低下も防ぐ。', null),
  ('sci_1_b4_002', '理科', 1, '動物の分類', 2, '哺乳類に当てはまるものはどれか。', 'ゾウ', array['ペンギン', 'カメ', 'サメ'], 'ペンギンは鳥類、カメは爬虫類、サメは魚類である。', null),
  ('sci_1_b4_003', '理科', 1, '動物の分類', 2, '無脊椎動物について間違っているものはどれか。', '背骨があるものもいる。', array['外骨格のものもいる。', '骨格が無いものもいる。', '殻におおわれているものもいる。'], '背骨がない動物を無脊椎動物という。', null),
  ('sci_1_b4_004', '理科', 1, '動物の分類', 1, '無脊椎動物はどれか。', 'ミミズ', array['ヘビ', 'ウナギ', 'サンショウウオ'], 'ヘビは脊椎動物の爬虫類、ウナギは脊椎動物の魚類、サンショウウオは脊椎動物の両生類、ミミズは無脊椎動物の環形動物である。', null),
  ('sci_1_b4_005', '理科', 1, '動物の分類', 2, '節足動物ではないものはどれか。', 'マイマイ', array['クモ', 'ミジンコ', 'トンボ'], 'クモは節足動物のクモ類、ミジンコは節足動物の甲殻類、トンボは節足動物の昆虫類、マイマイは軟体動物である。', null),
  ('sci_1_b4_006', '理科', 1, '動物の分類', 1, '甲殻類はどれか。', 'ザリガニ', array['バッタ', 'ホタテガイ', 'クモ'], '甲殻類は節足動物の仲間で、カニ、エビ、ザリガニなどである。バッタは節足動物の昆虫類、ホタテガイは軟体動物、クモは節足動物のクモ類である。', null),
  ('sci_1_b4_007', '理科', 1, '動物の分類', 1, '軟体動物はどれか。', 'アサリ', array['クラゲ', 'アメーバ', 'チョウ'], '軟体動物はイカ、タコ、貝のなかまで外とう膜がある。クラゲは腔腸動物、アメーバは原生動物、チョウは節足動物である。', null),
  ('sci_1_b4_008', '理科', 1, '動物の分類', 1, '昆虫類はどれか。', 'アリ', array['ムカデ', 'エビ', 'クモ'], '昆虫類は体が頭部、胸部、腹部に分かれていて胸部に3対のあしと2対のはねがある。ムカデは多足類、エビは甲殻類、クモはクモ類である。', null),
  ('sci_1_b4_009', '理科', 1, '動物の分類', 2, '外とう膜を持つなかまはどれか。', '軟体動物', array['昆虫類', '甲殻類', '脊椎動物'], '外とう膜は軟体動物の内臓をおおっている膜である。', null),
  ('sci_1_b4_010', '理科', 1, '動物の分類', 2, '両生類について、体表はどれか。', '皮膚', array['うろこ', '毛', '羽毛'], '両生類の体表はうすい皮膚でつねにぬれている。', null),
  ('sci_1_b4_011', '理科', 1, '動物の分類', 2, '両生類に当てはまるものはどれか。', 'サンショウウオ', array['クジラ', 'ペンギン', 'サメ'], 'クジラは哺乳類、ペンギンは鳥類、サメは魚類である。', null),
  ('sci_1_b4_012', '理科', 1, '動物の分類', 2, '鳥類について、体表はどれか。', '羽毛', array['うろこ', '皮膚', '毛'], '鳥類の体表は羽毛でおおわれ、体を保護するとともに体温が下がりにくくなっている。', null),
  ('sci_1_b4_013', '理科', 1, '動物の分類', 2, '鳥類に当てはまるものはどれか。', 'ダチョウ', array['コウモリ', 'ヤモリ', 'フナ'], 'コウモリは哺乳類、ヤモリは爬虫類、フナは魚類である。', null),
  ('sci_1_b4_014', '理科', 1, '動物の分類', 2, '魚類について、体表はどれか。', 'うろこ', array['皮膚', '毛', '羽毛'], '魚類は体表がうろこのものが多い。', null),
  ('sci_1_b4_015', '理科', 1, '動物の分類', 2, '魚類に当てはまるものはどれか。', 'イワシ', array['イルカ', 'ペンギン', 'サンショウウオ'], 'イルカは哺乳類、ペンギンは鳥類、サンショウウオは両生類である。', null),
  ('sci_1_b4_016', '理科', 1, '動物の分類', 2, '爬虫類について、体表はどれか。', 'うろこ', array['皮膚', '毛', '羽毛'], '爬虫類の体表はうろこやこうらでおおわれている。', null),
  ('sci_1_b4_017', '理科', 1, '動物の分類', 2, '爬虫類に当てはまるものはどれか。', 'ヘビ', array['カモノハシ', 'エイ', 'イモリ'], 'カモノハシは哺乳類、エイは魚類、イモリは両生類である。', null),
  ('sci_1_b4_018', '理科', 1, '植物のつくりとはたらき', 2, '被子植物だけの特徴はどれか。', '花びらのある花が咲く。', array['根茎葉の区別がある。', '種子でふえる。', '胚珠がある。'], '種子植物のうち胚珠が子房で包まれているのが被子植物である。被子植物の花は裸子植物と違い花弁(花びら)がある。', null),
  ('sci_1_b4_019', '理科', 1, '植物のつくりとはたらき', 1, '合弁花を選べ。', 'タンポポ', array['サクラ', 'マツ', 'アブラナ'], '被子植物の花は花弁が1枚1枚離れている離弁花と花弁のくっついている合弁花がある。タンポポやアサガオ、ツツジなどは合弁花で、アブラナ、サクラ、エンドウなどは離弁花である。', null),
  ('sci_1_b4_020', '理科', 1, '植物のつくりとはたらき', 1, 'まつかさとは何か。', '2年前の雌花', array['マツの果実', '2年前の雄花', 'マツの種子'], 'マツなどの裸子植物は雌花と雄花に分かれている。マツは受粉してから種子を放出するまで2年かかり、種子を放出してしまった雌花がまつかさとなる。', null),
  ('sci_1_b4_021', '理科', 1, '植物のつくりとはたらき', 2, '根のはたらきで間違っているものを選べ。', '光合成をする。', array['植物のからだをささえる。', '土の中の水を取り入れる。', '土の中の無機養分を取り入れる。'], '根は土の中から水と水に溶けている無機養分を取り入れるはたらきがある。また、植物の体をささえるのも重要なはたらきである。', null),
  ('sci_1_b4_022', '理科', 1, '植物のつくりとはたらき', 2, 'ツユクサやイネ、ユリなど単子葉類の根を何というか。', 'ひげ根', array['主根・側根', '仮根', '球根'], '被子植物は単子葉類と双子葉類に分けられるが、そのうち単子葉類の根はひげ根という多数の細いヒゲ状の根である。', null),
  ('sci_1_b4_023', '理科', 1, '植物のつくりとはたらき', 2, 'タンポポやアブラナ、エンドウなど双子葉類の根を何というか。', '主根・側根', array['ひげ根', '仮根', '球根'], '被子植物は単子葉類と双子葉類に分けられるが、そのうち双子葉類の根は太い主根から細い側根が枝分かれしている。', null),
  ('sci_1_b4_024', '理科', 1, '植物のつくりとはたらき', 2, '根の先端付近の毛のような細かい根を何というか。', '根毛', array['根冠', '仮根', '細根'], '根の先端付近には、根毛と呼ばれる細い毛のような細かい根がある。根毛は土の中に入り込んで根を土から抜けにくくし、さらに表面積を増やして水や養分を吸収しやすくするやくわりがある。', null),
  ('sci_1_b4_025', '理科', 1, '植物のつくりとはたらき', 2, '維管束のなかで、葉でつくられた栄養分が通る管を何というか。', '師管', array['道管', '消化管', '栄養管'], '道管と師管が集まって束になっているものを維管束という。道管には根から吸い上げた水が通り、師管には葉でつくられた栄養分が通っている。', null),
  ('sci_1_b4_026', '理科', 1, '植物のつくりとはたらき', 1, '蒸散が行われるのはどこか。', '気孔', array['細胞', '葉緑体', '道管'], '蒸散とは植物の体から水が水蒸気として出て行くことで、気孔で行われる。気孔からは蒸散で水蒸気が出て行く他、二酸化炭素、酸素などの気体が出入りする。', null),
  ('sci_1_b4_027', '理科', 1, '植物のつくりとはたらき', 2, '気孔が最も多く存在するところはどこか。', '葉の裏側', array['葉の表側', '茎', '根'], '気孔は孔辺細胞に囲まれた小さな穴で、とくに葉の裏側に多く存在する。', null),
  ('sci_1_b4_028', '理科', 1, '植物のつくりとはたらき', 2, '光合成するために必要ないものを選べ。', '酸素', array['光', '水', '二酸化炭素'], '光合成は、植物の細胞中の葉緑体で行われ、光のエネルギーを使い二酸化炭素と水を材料にしてデンプンなどの栄養分(有機養分)をつくるはたらきである。このときに栄養分とともに酸素も作られる。', null),
  ('sci_1_b4_029', '理科', 1, '植物のつくりとはたらき', 2, '蒸散を行なう理由として最も正しいものはどれか。', '根から水を吸い上げる原動力となる。', array['成長するためのエネルギーを作り出す。', '有機養分を作り出す。', '不要物の排出。'], '蒸散をさかんに行なうことで根からの水の吸い上げがさかんになる。つまり蒸散は根から水を吸い上げるための原動力となっている。また、それ以外にも植物の体の温度が高くなりすぎるのを防ぐはたらきもある。', null),
  ('sci_1_b4_030', '理科', 1, '植物のつくりとはたらき', 2, '光合成によって作られる物質はどれか。', 'デンプン', array['二酸化炭素', '水', '無機養分'], '光合成は、植物の細胞中の葉緑体で行われ、光のエネルギーを使い二酸化炭素と水を材料にしてデンプンなどの栄養分(有機養分)をつくるはたらきである。このときに栄養分とともに酸素も作られる。', null),
  ('sci_1_b4_031', '理科', 1, '植物の分類', 2, '単子葉類の特徴としてあっているものはどれか。', '平行脈', array['主根・側根', '茎の維管束が輪になっている。', '花弁が4枚か5枚'], '単子葉類は子葉が1枚、ひげ根、茎の維管束は全体に散らばり、葉脈は平行脈である。イネ、ツユクサ、トウモロコシ、ユリ、アヤメなど。', null),
  ('sci_1_b4_032', '理科', 1, '植物の分類', 1, '離弁花類はどれか。', 'アブラナ', array['タンポポ', 'ススキ', 'ソテツ'], '双子葉類は合弁花類と離弁花類に分けられる。離弁花類はサクラ、アブラナ、バラ、エンドウなどである。', null),
  ('sci_1_b4_033', '理科', 1, '植物の分類', 2, 'シダ植物やコケ植物はなにによってふえるか。', '胞子', array['種子', '分裂', '花粉'], 'シダ植物、コケ植物は花が咲かず種子を作らない。胞子によってふえる。', null),
  ('sci_1_b4_034', '理科', 1, '植物の分類', 2, 'シダ植物の特徴としてあっているものはどれか。', '維管束がある。', array['葉緑体は無い。', '根、茎、葉の区別はない。', '種子を作る。'], 'シダ植物は葉緑体のある植物である。根・茎・葉の区別があり維管束がある。花は咲かず種子は作らない、胞子によってふえる。イヌワラビやスギナ、ノキシノブなどがある。', null),
  ('sci_1_b4_035', '理科', 1, '植物の分類', 2, 'コケ植物の特徴としてあっているものはどれか。', '仮根がある。', array['根、茎、葉の区別がある。', '葉緑体は無い。', '維管束がある。'], 'コケ植物は葉緑体のある植物である。根、茎、葉の区別がなく維管束は無い、根と似た組織の仮根がある。体の表面から水分を取り入れる。胞子によってふえる。スギゴケ、ゼニゴケなどがある。', null),
  ('sci_1_b4_036', '理科', 1, '身のまわりの物質', 2, '有機物を燃やしたときに発生する気体は何か。', '二酸化炭素', array['水素', '炭素', '酸素'], '有機物とは炭素を含む物質のことなので燃やすと二酸化炭素が発生し、多くの場合は水素も含むので水も発生する。', null),
  ('sci_1_b4_037', '理科', 1, '身のまわりの物質', 2, '有機物を加熱すると何色になるか。', '黒色', array['赤色', '青色', '黄色'], '有機物とは炭素を含む物質のことなので、加熱すると炭素の色である黒色になる。', null),
  ('sci_1_b4_038', '理科', 1, '身のまわりの物質', 1, '無機物はどれか。', '炭素', array['石油', 'エタノール', 'プラスチック'], '有機物ではない物質を無機物といい、ガラスや金属、食塩などがある。また炭素や二酸化炭素、一酸化炭素も無機物である。', null),
  ('sci_1_b4_039', '理科', 1, '身のまわりの物質', 2, '金属に共通の性質として間違っているものはどれか。', '磁石にくっつく。', array['たたいて広げることができる。', '電気をよく通す。', 'みがくと独特の光沢がでる。'], '金属の共通の性質は熱伝導性、電気伝導性、延性、展性、金属光沢である。磁石につくのは鉄など一部の金属だけの性質である。', null),
  ('sci_1_b4_040', '理科', 1, '身のまわりの物質', 2, '石油などから人工的に合成された物質はどれか。', 'プラスチック', array['ガラス', 'アルミニウム', 'スチール'], 'プラスチックとは石油などを原料に人工的に合成された物質で、合成樹脂ともいわれる。', null),
  ('sci_1_b4_041', '理科', 1, '身のまわりの物質', 2, 'プラスチックの略称で間違っているものはどれか。', 'PK', array['PVC', 'PS', 'PP'], 'PVCはポリ塩化ビニル、PSはポリスチレン、PPはポリプロピレンの略称である。', null),
  ('sci_1_b4_042', '理科', 1, '身のまわりの物質', 1, '非金属はどれか。', 'ポリエチレン', array['銅', 'アルミニウム', 'ナトリウム'], 'ポリエチレンはプラスチックなので非金属である。', null),
  ('sci_1_b4_043', '理科', 1, '身のまわりの物質', 2, '液体の体積をはかる道具はどれか。', 'メスシリンダー', array['電子てんびん', 'ニュートンばねばかり', 'ろうと'], 'メスシリンダーは液体の体積をはかるための道具である。', null),
  ('sci_1_b4_044', '理科', 1, '身のまわりの物質', 2, '上皿てんびんは何をはかる道具か。', '質量', array['重さ', '体積', '面積'], '上皿てんびんや電子てんびんは質量をはかる道具である。', null),
  ('sci_1_b4_045', '理科', 1, '身のまわりの物質', 2, '水上置換で集める気体はどれか。', '酸素', array['アンモニア', '塩素', '硫化水素'], '水上置換で集めることのできる気体は水に溶けにくい気体である。', null),
  ('sci_1_b4_046', '理科', 1, '身のまわりの物質', 1, '腐卵臭のある気体はどれか。', '硫化水素', array['アンモニア', '水素', '窒素'], '硫化水素は腐卵臭(卵の腐ったようなにおい)がする。', null),
  ('sci_1_b4_047', '理科', 1, '身のまわりの物質', 1, '刺激臭のある気体はどれか。', '塩素', array['酸素', '水素', '二酸化炭素'], '塩素や塩化水素、アンモニアは刺激臭がある。', null),
  ('sci_1_b4_048', '理科', 1, '身のまわりの物質', 2, '空気の約2割を占める気体はどれか。', '酸素', array['二酸化炭素', '窒素', 'メタン'], '空気は窒素と酸素が主成分で、約8割が窒素、約2割が酸素である。', null),
  ('sci_1_b4_049', '理科', 1, '身のまわりの物質', 2, '塩素の性質として間違っているものはどれか。', '無色', array['漂白作用', '殺菌作用', '水に溶けやすい'], '塩素は刺激臭のある黄緑色の気体で、水に溶けやすく、空気より重い。有毒で漂白作用、殺菌作用がある。', null),
  ('sci_1_b4_050', '理科', 1, '身のまわりの物質', 2, '中性の水溶液にフェノールフタレイン溶液を加えたときの色はどれか。', '無色', array['赤色', '黄色', '青色'], 'フェノールフタレインはアルカリ性の水溶液に加えると赤色になるが、酸性や中性の水溶液に加えても無色のままである。', null),
  ('sci_1_b4_051', '理科', 1, '身のまわりの物質', 2, '亜鉛や鉄などの金属に加えたとき水素が発生するものはどれか。', 'うすい塩酸', array['石灰水', 'アンモニア水', 'フェノールフタレイン溶液'], '亜鉛や鉄などの金属にうすい塩酸を加えると水素が発生する。', null),
  ('sci_1_b4_052', '理科', 1, '身のまわりの物質', 2, '火山ガスの成分の一つである有毒な気体はどれか。', '硫化水素', array['窒素', '水素', '酸素'], '硫化水素は腐卵臭のある有毒な気体で、火山ガスの成分の1つである。', null),
  ('sci_1_b4_053', '理科', 1, '身のまわりの物質', 2, '下方置換であつめる気体はどれか。', '塩素', array['アンモニア', '窒素', '酸素'], '水に溶けやすく空気より重い気体は下方置換で集める。', null),
  ('sci_1_b4_054', '理科', 1, '身のまわりの物質', 2, '上方置換であつめる気体はどれか。', 'アンモニア', array['水素', '窒素', '塩素'], '水に溶けやすく空気より軽い気体は上方置換で集める。', null),
  ('sci_1_b4_055', '理科', 1, '身のまわりの物質', 2, '水に浮くプラスチックはどれか。', 'PP(密度0.9)', array['PET(密度1.4)', 'PS(密度1.06)', 'PVC(密度1.3)'], '水の密度は1なので、それより密度が小さい物質は水に浮く。', null),
  ('sci_1_b4_056', '理科', 1, '身のまわりの物質', 2, '密度はどれか。', '1cm³あたりの質量', array['1cm²にかかる力', '1秒間に移動した距離', '水100gに溶ける溶質の質量'], '密度とは1cm³あたりの質量のことである。', null),
  ('sci_1_b4_057', '理科', 1, '身のまわりの物質', 2, '水銀の密度は13.5である。水銀に入れたときに沈む金属はどれか。', '金(密度19.3)', array['鉄(密度7.87)', '銅(密度8.96)', 'アルミニウム(密度2.70)'], '水銀の密度13.5より密度が小さければ浮き、大きければ沈む。', null),
  ('sci_1_b4_058', '理科', 1, '身のまわりの物質', 1, '密度の単位はどれか。', 'g/cm³', array['N/m²', 'Pa', 'Km/h'], '密度は1cm³あたりの質量で、質量(g)÷体積(cm³)で求められる。', null),
  ('sci_1_b4_059', '理科', 1, '水溶液', 1, '食塩水の溶媒は何か。', '水', array['食塩', '食塩水', 'なし'], '溶液は溶質が溶媒に溶けた液のことで、溶けている物質が溶質、溶かしている液体が溶媒である。食塩水の場合、溶媒が水で溶質が食塩である。', null),
  ('sci_1_b4_060', '理科', 1, '水溶液', 2, '物質が水に溶けたとき、物質の粒子は（　　）。', '均一に広がる', array['なくなる', '底の近くにかたまる', '水面近くにかたまる'], '物質が水に溶けたとき、物質の粒子が全体に均一に広がるため水溶液は透明になる。このとき水溶液のどの部分も濃さは同じになる。', null),
  ('sci_1_b4_061', '理科', 1, '水溶液', 2, 'ある物質が限界まで溶けた水溶液を何というか。', '飽和水溶液', array['完全水溶液', '限界水溶液', '溶水溶液'], '一定の水に溶ける物質には限界があり、その限界まで溶かした水溶液を飽和水溶液という。', null),
  ('sci_1_b4_062', '理科', 1, '水溶液', 2, '100gの水に溶ける物質の限界の質量を何というか。', '溶解度', array['飽和溶質量', '限界質量', '質量パーセント濃度'], '一定の水に溶ける物質には限界がある。100gの水に溶ける物質の限界の質量を溶解度という。', null),
  ('sci_1_b4_063', '理科', 1, '水溶液', 1, '塩化銅水溶液の色を答えよ。', '青色', array['無色', '赤かっ色', '黄色'], '水溶液はすべて透明だが、色のついたものもある。塩化銅水溶液や硫酸銅水溶液は青色である。', null),
  ('sci_1_b4_064', '理科', 1, '水溶液', 2, '固体を水に溶かして、再び結晶として取り出すことを何というか。', '再結晶', array['蒸発', '蒸留', '再取出'], '水溶液の温度を下げたり、水を蒸発させたりして、水に溶けた固体を再び結晶として取り出すことを再結晶という。', null),
  ('sci_1_b4_065', '理科', 1, '水溶液', 2, '溶質の質量÷溶液の質量×100この式で計算できるものは何か。', '質量パーセント濃度', array['溶解度', '飽和水溶液', '密度'], '溶液の質量に対する溶質の質量の割合を%で表したのが質量パーセント濃度である。', null),
  ('sci_1_b4_066', '理科', 1, '水溶液', 2, '塩化ナトリウムを再結晶させるのに適した方法はどれか。', '水を蒸発させる。', array['高い温度の水にできる限り溶かしてから冷やす。', '水を加える。', 'よくかき混ぜる。'], '塩化ナトリウムの溶解度は温度によってあまり変化しないので、再結晶させるには水を蒸発させるのが適している。', null),
  ('sci_1_b4_067', '理科', 1, '水溶液', 2, 'すべての水溶液に共通な性質として間違っているものはどれか。', '無色である。', array['時間がたっても溶けたものは出てこない。', 'どの部分も同じ濃さである。', '透明である。'], '水溶液には色のついているものもある。', null),
  ('sci_1_b4_068', '理科', 1, '水溶液', 2, '液体中に混ざっている沈殿物などの固体を、液体と分けることを何というか。', 'ろ過', array['再結晶', '蒸留', '飽和'], 'ろ過とはろ紙などを用いて液体中に混ざっている沈殿物などの固体を液体と分けることである。', null),
  ('sci_1_b4_069', '理科', 1, '光の性質', 2, '光が空気から水のように違う物質へ進むときその（　　）面で大部分は屈折し、一部は反射する。', '境界', array['斜', '前', '基準'], '光が空気から水やガラスへ斜めに進むとき、その境界面で屈折する。', null),
  ('sci_1_b4_070', '理科', 1, '光の性質', 2, '光が水中から空気中へ出て行くときの屈折角の限界は何度か。', '90度', array['48.6度', '180度', '0度'], '境界面に垂直な直線と屈折光の角度が屈折角なので、屈折角は90度より大きくはならない。', null),
  ('sci_1_b4_071', '理科', 1, '光の性質', 2, '全反射を利用しているのはどれか。', '光ファイバー', array['ルーペ', 'カメラ', '望遠鏡'], '光ファイバーは全反射の性質を利用したもので、電話線などに使われている。', null),
  ('sci_1_b4_072', '理科', 1, '光の性質', 2, '物体を焦点より遠くに置いたときに、凸レンズの反対側のスクリーンにうつる像を何というか。', '実像', array['虚像', '正立像', 'レンズ像'], '物体を焦点より遠くに置くと、実像ができる。実像は物体と反対側に置いたスクリーンにできる倒立の像である。', null),
  ('sci_1_b4_073', '理科', 1, '光の性質', 2, '物体を焦点より近くに置いたときに、凸レンズの反対側からのぞいて見える像を何というか。', '虚像', array['実像', '屈折像', '倒立像'], '物体を焦点より近くに置くと虚像ができる。虚像は物体の反対側から凸レンズをのぞいたときに見える正立の大きな像である。', null),
  ('sci_1_b4_074', '理科', 1, '光の性質', 2, '虚像では無いものはどれか。', '映画のスクリーンに映る像', array['鏡に映る像', 'ルーペをのぞいて見える像', '水中の物体が浮き上がって見える像'], '映画のスクリーンに映るのは実像、ほかは全て虚像である。', null),
  ('sci_1_b4_075', '理科', 1, '光の性質', 2, '凸レンズから8cmのところに物体をおいたとき、レンズの反対側のレンズから8cmのところにスクリーンを置くとはっきりと像が写った。このレンズの焦点距離は何cmか。', '4cm', array['8cm', '16cm', '12cm'], '物体からレンズまでの距離と、レンズからスクリーンまでの距離が等しくなるのはちょうど焦点距離の2倍の時である。', null),
  ('sci_1_b4_076', '理科', 1, '光の性質', 2, '焦点距離が10cmの凸レンズで、高さ6cmの物体をレンズから20cmのところに置いたとき、できる実像の高さは何cmか。', '6cm', array['3cm', '9cm', '12cm'], '物体からレンズまでの距離が焦点距離の2倍のときにできる実像は物体と同じ大きさである。', null),
  ('sci_1_b4_077', '理科', 1, '光の性質', 2, '焦点距離が6cmの凸レンズで物体をレンズから18cmのところに置いたとき、実像のできるスクリーンの位置はレンズから何cmか。', '9cm', array['6cm', '12cm', '15cm'], '物体からレンズまでの距離が焦点距離の2倍より遠いと、スクリーンは焦点と焦点距離の2倍の間になる。つまりこの場合は6cmより大きく12cmより小さい距離である。', null),
  ('sci_1_b4_078', '理科', 1, '光の性質', 2, '焦点距離が6cmの凸レンズで、高さ12cmの物体をレンズから15cmのところに置いたとき、できる実像の高さは何cmか。', '8cm', array['12cm', '16cm', '20cm'], '物体とレンズの距離が焦点距離の2倍より遠いと、物体より小さい像ができる。つまりこの場合12cmより小さい像になる。', null),
  ('sci_1_b4_079', '理科', 1, '光の性質', 2, '焦点距離が12cmの凸レンズで物体をレンズから18cmのところに置いたとき、実像のできるスクリーンの位置はレンズから何cmか。', '36cm', array['6cm', '12cm', '24cm'], '物体とレンズとの距離が焦点距離の2倍より近いと、スクリーンの位置は焦点距離の2倍より遠くになる。つまりこの場合は24cmより遠くである。', null),
  ('sci_1_b4_080', '理科', 1, '光の性質', 2, '焦点距離が6cmの凸レンズで、高さ5cm物体をレンズから9cmのところに置いたとき、できる実像の高さは何cmか。', '10cm', array['3cm', '2.5cm', '5cm'], '物体とレンズとの距離が焦点距離の2倍より近いと、物体より大きな像ができる。つまりこの場合は5cmより大きな像である。', null),
  ('sci_1_b4_081', '理科', 1, '音の性質', 1, '音を伝えないのはどれか。', '真空', array['気体', '液体', '固体'], '音は音源の振動が波となって物質を伝わっていく。物質が何もない真空では音は伝わらない。', null),
  ('sci_1_b4_082', '理科', 1, '音の性質', 2, '空気中の音の速さはどのくらいか。', '約340m/s', array['約100m/s', '約1500m/s', '約7800m/s'], '音が空気中を伝わる速さは約340m/sである。温度などの条件で少し変化する。', null),
  ('sci_1_b4_083', '理科', 1, '音の性質', 2, '1秒間に振動する回数を何というか。', '振動数', array['振幅', '波長', '周期'], '1秒間に振動する回数を振動数という。振動数の単位はHz（ヘルツ)である。', null),
  ('sci_1_b4_084', '理科', 1, '音の性質', 2, '振幅が大きいとどんな音になるか。', '大きい音', array['高い音', '低い音', '小さい音'], '振動の大きさ、振れ幅のことを振幅という。振幅が大きいほど大きな音になる。', null),
  ('sci_1_b4_085', '理科', 1, '音の性質', 2, '振動数が多いとどんな音になるか。', '高い音', array['低い音', '小さい音', '大きい音'], '音の高低は振動数によって決まる。振動数が多いほど高い音が出る。', null),
  ('sci_1_b4_086', '理科', 1, '音の性質', 2, '弦で高い音を出す方法として間違っているものはどれか。', '弦を強く弾く', array['短い弦にする', '細い弦にする', '弦を強く張る'], '弦楽器の弦は細いほど、短いほど、強く張るほど高い音が出る。弦を強く弾くと振幅が大きくなるので大きな音が出る。', null),
  ('sci_1_b4_087', '理科', 1, '力のはたらき', 2, '力のはたらきとして間違っているものはどれか。', '物体の質量を変える', array['物体を変形させる', '物体を支える', '物体の動きを変える'], '力のはたらきは3つ。物体を変形させる。物体を支える。物体の動き(速さや向き)を変える。', null),
  ('sci_1_b4_088', '理科', 1, '力のはたらき', 1, '力の単位はどれか。', 'N', array['F', 'g', 'm'], '力の単位はN(ニュートン)である。', null),
  ('sci_1_b4_089', '理科', 1, '力のはたらき', 1, '重さとは何か。', '物体にはたらく重力', array['物体の質量', '物体そのものの量', '物体を支える力'], '重さとは物体にはたらく重力のことである。物体そのもの量を質量という。重さと質量は区別しなければならない。', null),
  ('sci_1_b4_090', '理科', 1, '力のはたらき', 2, '変形した物体がもとへもどろうとする力を何というか。', '弾性力', array['変形力', 'まさつ力', '回復力'], '物体が変形したときにもとに戻ろうとする力を弾性力という。ばねなどがその例である。', null),
  ('sci_1_b4_091', '理科', 1, '力のはたらき', 2, '地球が物体を地球の中心に向かって引く力を何というか。', '重力', array['弾性力', '抗力', '中心力'], '地球や月が物体をその中心に向かって引く力が重力である。重力はすべての物体にはたらき、離れていてもはたらく力である。', null),
  ('sci_1_b4_092', '理科', 1, '力のはたらき', 2, '机の上や床の上に置かれた物体を支える力を何というか。', '抗力', array['まさつ力', '重力', '反発力'], '水平な床や机の上に物体を置いたとき、その面が上向きに物体を押して物体を支える力が抗力である。垂直抗力ともいう。', null),
  ('sci_1_b4_093', '理科', 1, '力のはたらき', 2, '物体どうしが触れ合う面で、動かそうとする力と反対向きにはたらく力を何というか。', 'まさつ力', array['抗力', '重力', '反発力'], '摩擦力は物体どうしがふれあう面ではたらく。物体が動こうとする方向の反対向きの力である。静止まさつ力と動まさつ力がある。', null),
  ('sci_1_b4_094', '理科', 1, '力のはたらき', 2, '2力がつり合う条件として間違っているものはどれか。', '2力の種類が等しい。', array['2力の大きさが等しい。', '2力が反対向きである。', '作用線が一致する。'], '力の種類が異なっていても大きさが等しく、反対向きで同一直線上にある2力はつり合う。', null),
  ('sci_1_b4_095', '理科', 1, '力のはたらき', 2, '床や机など水平な面に物体をおいた場合、物体にはたらく重力とつり合っている力は何か。', '垂直抗力', array['大気圧', '万有引力', '摩擦力'], '変形した床や机の面がもとに戻ろうとする力が抗力であり、これが物体に働く重力とつりあっている。', null),
  ('sci_1_b4_096', '理科', 1, '力のはたらき', 2, '物体どうしが触れ合う面ではたらく、物体が動こうとする方向の反対向きの力を何というか。', '摩擦力', array['抗力', '引力', '斥力'], '物体どうしが触れ合う面ではたらく、物体が動こうとする方向の反対向きの力を摩擦力という。 摩擦のある面で物体を押しても物体が静止しているときは物体を押す力と摩擦力がつりあっており、このときの摩擦力を静止摩擦力という。 また、摩擦のある面で物体を滑らせた場合、運動と逆の方向に摩擦力が働くこのときの摩擦力を動摩擦力という。', null),
  ('sci_1_b4_097', '理科', 1, '地震', 2, '地震が発生した場所のことを何というか。', '震源', array['震央', '断層', 'プレート'], '地下の地震が発生した場所のことを震源という。震源の真上の地表の地点が震央である。', null),
  ('sci_1_b4_098', '理科', 1, '地震', 2, '地震の波のうち、伝わる速さの速い波を何というか。', 'P波', array['S波', 'T波', 'PKP波'], '地震の波のうち最も速い波がP波で小さな揺れをおこす、次に到達するのがS波でおおきなゆれをおこす。', null),
  ('sci_1_b4_099', '理科', 1, '地震', 2, '地震のゆれのうち、あとからくる大きな揺れのことを何というか。', '主要動', array['震度', 'マグニチュード', '初期微動'], '先に伝わるP波による小さな揺れが初期微動、あとからくるP波による大きな揺れが主要動である。', null),
  ('sci_1_b4_100', '理科', 1, '地震', 2, '震源からの距離に比例するのはどれか。', '初期微動継続時間', array['マグニチュード', '到達時刻', '地震波の速度'], 'P波とS波の到達時刻の差を初期微動継続時間という。初期微動継続時間は震源からの距離に比例する。', null),
  ('sci_1_b4_101', '理科', 1, '地震', 2, 'ある地点でのゆれの強さを表すのはどれか。', '震度', array['エネルギー', 'マグニチュード', '主要動'], '震度はある地点でのゆれの強さを表す。0〜7まで10段階にわけられる(5、6は弱と強がある)', null),
  ('sci_1_b4_102', '理科', 1, '地震', 2, '地震の規模、エネルギーの大きさを表すのはどれか。', 'マグニチュード', array['震度', 'プレート', '主要動'], 'マグニチュード(M)は地震の規模、エネルギーの大きさを表す。マグニチュードが1増えるとエネルギーは約32倍になる', null),
  ('sci_1_b4_103', '理科', 1, '地震', 2, '地震のよっておこった大地のずれを何というか。', '断層', array['しゅう曲', '地殻', 'プレート'], '地震によっておこった大地のずれが断層である。岩盤、地層が大きな力によって断ち切られてずれる。とくに繰り返し動いた断層を活断層といい、これからも動く可能性が高いのでそこで地震が起こりやすい。', null),
  ('sci_1_b4_104', '理科', 1, '地震', 2, '震央とは何か。', '地震が発生した場所の真上の地表の地点。', array['地下の地震が発生した場所。', '繰り返し地震が発生して、これからも地震が起こりやすい場所。', '地球の中心。'], '地下の地震が発生した場所のことを震源といい、震源の真上の地表の地点が震央である。', null),
  ('sci_1_b4_105', '理科', 1, '地震', 2, '初期微動について誤っているのはどれか。', 'マグニチュードが大きいほど長く続く。', array['震源からの遠いほど続く時間が長くなる。', 'P波によって起こされるゆれである。', '最初の小さな揺れのことである。'], '初めに到達するP波がひきおこすちいさな揺れが初期微動である。P波とS波の到達時刻の差が初期微動継続時間となり、震源から遠いほど長く続く。', null),
  ('sci_1_b4_106', '理科', 1, '地震', 1, '震度は何段階あるか。', '10', array['7', '8', '9'], 'ある地点でのゆれの強さを表すのが震度である。0〜7まであり、5、6は弱と強があるため10段階にわけられる。', null),
  ('sci_1_b4_107', '理科', 1, '地震', 3, 'マグニチュードが1大きくなるとエネルギーは約何倍になるか。', '32', array['2', '12', '100'], 'マグニチュード(M)は地震の規模、エネルギーの大きさを表す。マグニチュードが1増えるとエネルギーは約32倍になる。', null),
  ('sci_1_b4_108', '理科', 1, '地震', 2, 'その動きが地震の原因となっている巨大な岩盤を何というか。', 'プレート', array['マグマ', 'マントル', 'コア'], '地球表面をおおう、巨大な岩盤をプレートという。プレートの動きが地震の原因となっている。', null),
  ('sci_1_b4_109', '理科', 1, '地震', 2, '活断層について誤っているのはどれか。', '日本国内にはあまり存在しない。', array['岩盤、地層が断ち切られてずれたものである。', '繰り返し、動いた断層である。', 'これからも動く可能性が高く、そこで地震が起きやすい。'], '地震によっておこった大地のずれを断層という。岩盤、地層が大きな力によって断ち切られてずれる。特に、繰り返し動いた断層を活断層といい、これからも動く可能性が高いのでそこで地震が起こりやすい。日本各地に無数に存在する。', null),
  ('sci_1_b4_110', '理科', 1, '地層と化石', 2, '地層ができた当時の環境を知る手がかりとなる化石を何というか。', '示相化石', array['化石燃料', '示準化石', '環境化石'], '地層ができた当時の環境を知る手がかりとなるのは示相化石である。示相化石になるのは限られた環境でしか生存できない生物である。', null),
  ('sci_1_b4_111', '理科', 1, '地層と化石', 2, '地層ができた時代をしる手がかりとなる化石を何というか。', '示準化石', array['化石燃料', '示相化石', '時代化石'], '地層ができた時代を知る手がかりとなるのは示準化石である。示準化石になるのは限られた時代に広い地域にっ生存していた生物である。', null),
  ('sci_1_b4_112', '理科', 1, '地層と化石', 1, '古生代の化石はどれか。', 'フズリナ', array['ビカリア', 'アンモナイト', '恐竜'], 'フズリナや三葉虫は古生代の代表的な示準化石である。', null),
  ('sci_1_b4_113', '理科', 1, '地層と化石', 1, '中生代の化石はどれか。', 'アンモナイト', array['ビカリア', 'フズリナ', 'マンモス'], 'アンモナイトや恐竜は中生代の代表的な示準化石である。', null),
  ('sci_1_b4_114', '理科', 1, '地層と化石', 1, '新生代の化石はどれか。', 'ビカリア', array['アンモナイト', 'フズリナ', '三葉虫'], 'ビカリアやマンモスは新生代の代表的な示準化石である。', null),
  ('sci_1_b4_115', '理科', 1, '地層と化石', 2, 'サンゴの化石が示す環境はどれか。', '暖かくて浅い海', array['冷たくて浅い海', '暖かくて深い海', 'きれいで深い海'], 'サンゴが生息するのは暖かくて浅い海である。', null),
  ('sci_1_b4_116', '理科', 1, '地層と化石', 2, '示相化石の条件はどれか。', '限られた環境でしか生存できない生物', array['限られた時代に生存していた生物', 'あらゆる環境に生存できる生物', '現在にはいない生物'], '地層ができた当時の環境を知るてがかりとなる化石を示相化石という。 示相化石になるのは限られた環境でしか生存できない生物である。', null),
  ('sci_1_b4_117', '理科', 1, '地層と化石', 2, '示準化石の条件はどれか。', '限られた時代に広い地域で生存していた生物', array['限られた環境でしか生存できない生物', '限られた時代に狭い地域で生存していた生物', '現在でも生存している生物'], '地層ができた時代を知る手がかりとなる化石を示準化石という。 示準化石になるのは限られた時代に、広い地域に生存していた生物である。', null),
  ('sci_1_b4_118', '理科', 1, '地層と化石', 2, '化石を含んでいる可能性がある岩石はどれか。', '石灰岩', array['流紋岩', '玄武岩', '花こう岩'], '化石は堆積岩に含まれる。選択肢の中で堆積岩は石灰岩である', null),
  ('sci_1_b4_119', '理科', 1, '地層と化石', 2, 'フズリナの化石が見つかった地層はどの時代のものか。', '古生代', array['中生代', '新生代第三紀', '新生代第四紀'], 'フズリナは古生代に繁栄した有孔虫の一種であり、古生代の示準化石である。', null),
  ('sci_1_b4_120', '理科', 1, '地層と化石', 2, 'ステゴサウルスの化石が見つかった地層はどの時代のものか。', '中生代', array['古生代', '新生代第三紀', '新生代第四紀'], 'ステゴサウルスなど恐竜は中生代に繁栄した脊椎動物である。', null),
  ('sci_1_b4_121', '理科', 1, '地層と化石', 2, 'ビカリアの化石が見つかった地層はどの時代のものか。', '新生代第三紀', array['古生代', '中生代', '新生代第四紀'], 'ビカリアは新生代第三紀に繁栄した巻き貝の仲間である。', null),
  ('sci_1_b4_122', '理科', 1, '地層と化石', 2, '地表の岩石が太陽の熱や水のはたらきで表面からぼろぼろにくずれ砂や泥に変わっていくことを何というか。', '風化', array['侵食', '堆積', '劣化'], '地表の岩石が太陽の熱や水のはたらきで表面からぼろぼろにくずれ砂や泥に変わっていくことを風化という。風化した岩石を雨水や流水がけずりとることが侵食、河口や海の底に、れき、砂、泥が平らに積もっていくことが堆積である。', null),
  ('sci_1_b4_123', '理科', 1, '地層と化石', 2, '最も粒の小さい堆積岩はどれか。', '泥岩', array['砂岩', 'れき岩', '流紋岩'], '堆積岩の泥岩、砂岩、れき岩は粒の大きさで区別され、1/16mm以下が泥岩、1/16mmから2mmが砂岩、2mm以上がれき岩である。', null),
  ('sci_1_b4_124', '理科', 1, '地層と化石', 2, '生物の遺骸が水に溶けて固まった堆積岩で、塩酸をかけると二酸化炭素が発生するのはどれか。', '石灰岩', array['チャート', '凝灰岩', 'れき岩'], 'チャートと石灰岩は生物の遺骸が水に溶けて固まったものである。 チャートの主な成分は二酸化ケイ素で石灰岩は炭酸カルシウムである。 石灰岩のほうが柔らかく容易に傷がつき、塩酸をかけると二酸化炭素が発生する。', null),
  ('sci_1_b4_125', '理科', 1, '地層と化石', 2, '地層が、長い期間大きな力を受けて波打つように曲がったものを何というか。', 'しゅう曲', array['断層', '隆起', '沈降'], '長期間大きな力を受けて地層が波打つように曲がったものをしゅう曲という。いっぽう断層は大きな力で地層が断ち切られたものである。', null),
  ('sci_1_b4_126', '理科', 1, '地層と化石', 2, '岩石を風化させるものとして適当でないものはどれか。', 'マグマ', array['風雨', '太陽の熱', '水'], '地表の岩石が風雨の影響や太陽の熱、水のはたらきで表面からぼろぼろにくずれ砂や泥に変わっていくことを風化という。', null),
  ('sci_1_b4_127', '理科', 1, '地層と化石', 2, '堆積とは何か。', 'れきや砂、泥が河口や海の底につもること。', array['流水が岩石をけずること。', 'れきや砂、泥が川によって運ばれること。', '大きな石のこと。'], '風化した岩石を雨水や流水がけずりとることが侵食、削り取られたれき、砂、泥が川によって運ばれることが運搬、流れがゆるやかになった河口や海の底に、れき、砂、泥が平らに積もっていくことが堆積である。', null),
  ('sci_1_b4_128', '理科', 1, '地層と化石', 2, '地層がつくられる主な場所どこか。', '海底', array['山の上', '草原', '川の上流'], '地層は、河口や海底で土砂が堆積を繰り返すことによってつくられる。', null),
  ('sci_1_b4_129', '理科', 1, '地層と化石', 2, '泥岩、砂岩、れき岩は粒の大きさで区別されるが、砂岩とれき岩の境は何mmか。', '2mm', array['20mm', '0.2mm', '0.02mm'], '泥岩、砂岩、れき岩は粒の大きさによって区別され、 泥岩と砂岩の境は 1/16mm、 砂岩とれき岩との境は2mmである。', null),
  ('sci_1_b4_130', '理科', 1, '地層と化石', 1, 'チャートの主な成分は何か。', '二酸化ケイ素', array['炭酸カルシウム', '二酸化炭素', '塩酸'], 'チャートと石灰岩は生物の遺骸が水に溶けて固まったもので、チャートの主な成分は二酸化ケイ素、石灰岩は炭酸カルシウムである。', null),
  ('sci_1_b4_131', '理科', 1, '地層と化石', 2, '波による侵食と海岸線の隆起によってできた階段状の地形を何というか。', '海岸段丘', array['海岸しゅう曲', '海岸断層', '階段海岸'], '波による侵食と海岸線の隆起によってできた階段状の地形を海岸段丘という。', null),
  ('sci_1_b4_132', '理科', 1, '火山と火成岩', 2, '火山噴出物で火口から流れ出す高温の液体状、またはそれが固まったものを何というか。', '溶岩', array['凝灰岩', '堆積岩', '火山灰'], '地下のマグマが地上に流れでたものを溶岩という。液体状でも冷えて固まったものも両方溶岩である。', null),
  ('sci_1_b4_133', '理科', 1, '火山と火成岩', 2, '火山の火口から吹き飛ばされたマグマが空中で冷えて固まったものを何というか。', '火山弾', array['火山灰', '火山ガス', 'マグマだまり'], '火山弾は噴火のときにマグマが完全な固体ではないまま空中に噴出され、飛行中に特定の形にかたまったものである。 球状や紡錘状などがある。', null),
  ('sci_1_b4_134', '理科', 1, '火山と火成岩', 2, '火山噴出物の一つで、白っぽく小さな穴がたくさんあいていて軽い石を何というか。', '軽石', array['火山灰', '火山弾', '凝灰岩'], '軽石は固体の火山噴出物の白っぽい岩石である。ガスの抜けた穴が無数にあいていて軽い。', null),
  ('sci_1_b4_135', '理科', 1, '火山と火成岩', 2, '火山噴出物の固体のうち粒が2mm以下のものを何というか。', '火山灰', array['凝灰岩', '火山弾', '火山れき'], '火山灰は固体の火山噴出物で、 非常に小さい破片である。固体の火山噴出物は大きさで呼び名が異なり、もっとも小さい直径が2mm以下のものが火山灰である。', null),
  ('sci_1_b4_136', '理科', 1, '火山と火成岩', 2, '火山噴出物の固体のうち粒が2mm以上のものを何というか。', '火山れき', array['凝灰岩', '火山弾', '火山灰'], '固体の火山噴出物で、直径2mmから64mmのものを火山れきと呼ぶ。', null),
  ('sci_1_b4_137', '理科', 1, '火山と火成岩', 2, 'マグマのねばりけが小さいと岩石の色はどうなるか。', '黒っぽくなる', array['白っぽくなる', 'どちらともいえない', '灰色になる'], 'マグマのねばりけが小さいと冷えて固まったときに岩石は黒っぽくなる。', null),
  ('sci_1_b4_138', '理科', 1, '火山と火成岩', 2, '噴火が激しいのはどれか。', 'マグマのねばりけが大きい', array['マグマのねばりけが小さい', 'マグマのねばりけが中間', 'ねばりけは関係ない'], 'マグマのねばりけが大きいと噴火のようすは激しくなり、ねばりけが小さいと噴火は穏やかになる。', null),
  ('sci_1_b4_139', '理科', 1, '火山と火成岩', 2, 'マグマのねばりけが大きい火山はどれか。', '有珠山', array['三原山', 'キラウェア', '桜島'], '有珠山や昭和新山、平成新山などはマグマのねばりけが大きい、マウナロアやキラウェアなどは粘り気がちいさい、桜島、三原山は中間である。', null),
  ('sci_1_b4_140', '理科', 1, '火山と火成岩', 2, 'マグマのねばりけが大きいと火山の形はどうなるか。', 'ドーム状', array['傾斜がゆるやか', '円すい形', 'ねばりけは関係ない'], 'マグマのねばりけが大きいとドーム状になり、ねばりけが小さいと傾斜がゆるやかになる。中間は円すい形になる。', null),
  ('sci_1_b4_141', '理科', 1, '火山と火成岩', 2, '地下数kmのマグマが蓄えられているところを何というか。', 'マグマだまり', array['プレート', 'マントル', '深成岩'], '地下数十kmの深いところで生じたマグマが比較的浅い数kmのところまで上昇してマグマだまりをつくる。火山が噴火するときに、マグマはマグマだまりから岩石の割れ目などを突き破って地表に出てくる。', null),
  ('sci_1_b4_142', '理科', 1, '火山と火成岩', 2, 'マグマが固まってできた岩石を何というか。', '火成岩', array['凝灰岩', '堆積岩', '石灰岩'], 'マグマが冷えて固まった岩石を火成岩という。火成岩には深成岩と火山岩がある。', null),
  ('sci_1_b4_143', '理科', 1, '火山と火成岩', 2, '深成岩の説明のうち間違っているものはどれか。', '石基がみられる。', array['鉱物の結晶がおおきい。', 'ゆっくり冷えて固まった。', '等粒状組織である。'], 'マグマが冷えて固まった岩石のうち、地下の深いところでゆっくり冷えて固まった岩石を深成岩という。 マグマが地下深くのマグマだまりなどでゆっくり冷えて固まると、 それぞれの鉱物の結晶が成長して大きくなる。この大きな鉱物の結晶が組み合わさった組織を等粒状組織という。', null),
  ('sci_1_b4_144', '理科', 1, '火山と火成岩', 2, '火山岩の説明のうち間違っているものはどれか。', '地下深くで固まった。', array['斑晶がみられる。', '斑状組織である。', '急に冷えて固まった。'], 'マグマが固まってできた岩石のうち、地下の浅いところや地上で急に冷え固まった岩石を 火山岩という。 火山岩の組織は斑状組織で、地下にあるときに成長した結晶(斑晶)と 地表近くで急に冷えて固まったために結晶になれなかった部分(石基)からできている。', null),
  ('sci_1_b4_145', '理科', 1, '火山と火成岩', 1, '深成岩はどれか。', '花こう岩', array['凝灰岩', '流紋岩', '砂岩'], '深成岩には花こう岩、せん緑岩、斑れい岩がある。', null),
  ('sci_1_b4_146', '理科', 1, '火山と火成岩', 1, '火山岩はどれか。', '玄武岩', array['せん緑岩', '泥岩', '石灰岩'], '火山岩には流紋岩、安山岩、玄武岩がある。', null),
  ('sci_1_b4_147', '理科', 1, '火山と火成岩', 1, '無色鉱物はどれか。', 'チョウ石', array['クロウンモ', 'カクセン石', 'キ石'], 'チョウ石は白色または薄桃色や灰色で決まった方向に割れる鉱物である。 ほとんどの火成岩に含まれている。', null),
  ('sci_1_b4_148', '理科', 1, '火山と火成岩', 2, '無色、または白色で不規則な形に割れる鉱物はどれか。', 'セキエイ', array['カクセン石', 'カンラン石', 'チョウ石'], 'セキエイは無色または白色で、不規則に割れる鉱物である。 花こう岩や流紋岩などに含まれている。', null),
  ('sci_1_b4_149', '理科', 1, '火山と火成岩', 2, '黒色でうすく板状にはがれる鉱物はどれか。', 'クロウンモ', array['キ石', 'カンラン石', 'カクセン石'], 'クロウンモは黒色、褐色でうすくはがれる。 流紋岩、花こう岩や安山岩、せん緑岩などに含まれる鉱物である', null),
  ('sci_1_b4_150', '理科', 1, '火山と火成岩', 2, '黒色または黒緑色で、長い柱状に割れる鉱物はどれか。', 'カクセン石', array['クロウンモ', 'キ石', 'カンラン石'], 'カクセン石は黒色または黒緑色で長い柱状に割れる鉱物である。 流紋岩、花こう岩や安山岩、せん緑岩などに含まれる。', null),
  ('sci_1_b4_151', '理科', 1, '火山と火成岩', 2, '黒緑色または暗褐色で、短い柱状に割れる鉱物はどれか。', 'キ石', array['チョウ石', 'カクセン石', 'カンラン石'], '黒緑色または暗褐色で短い柱状に割れる鉱物である。 玄武岩、斑れい岩、せん緑岩、安山岩などにふくまれる', null),
  ('sci_1_b4_152', '理科', 1, '動物の分類', 2, '哺乳類について、なかまのふやしかたはどれか。', '胎生', array['卵生(殻なし)', '卵生(殻あり)', '卵生と胎生の両方'], '哺乳類は雌が子を体内である程度成長させてから産む。', null),
  ('sci_1_b4_153', '理科', 1, '動物の分類', 2, '両生類について、なかまのふやしかたはどれか。', '卵生(殻なし)', array['卵生(殻あり)', '胎生', '卵生と胎生の両方'], '両生類は水中に卵を産むので卵に殻はない。', null),
  ('sci_1_b4_154', '理科', 1, '動物の分類', 2, '両生類について、呼吸の仕方はどれか。', '子がえら呼吸、親が肺呼吸', array['えら呼吸のみ', '肺呼吸のみ', '子が肺呼吸、親がえら呼吸'], '両生類の子(幼生)は水中で生活するのでえらで呼吸するが、親(成体)になると陸上で生活し肺呼吸と皮膚呼吸を行なう。', null),
  ('sci_1_b4_155', '理科', 1, '植物のつくりとはたらき', 2, '種子植物とは（　　）植物である。', '花を咲かせる', array['胞子でふえる', '子房がある', '葉・茎・根の区別がない'], '花を咲かせ、種子でなかまをふやす植物を種子植物と呼び、被子植物と裸子植物に分けられる。', null),
  ('sci_1_b4_156', '理科', 1, '植物のつくりとはたらき', 2, '裸子植物の特徴はどれか。', '胚珠がむき出しになっている。', array['1つの花におしべとめしべがある。', '果実ができる。', '子房が胚珠を包んでいる。'], '種子植物のうち胚珠がむき出しになっているのが裸子植物である。マツ、イチョウ、ソテツ、スギなど。裸子植物の花は花弁がなく、また雄花と雌花に分かれている。', null),
  ('sci_1_b4_157', '理科', 1, '植物のつくりとはたらき', 2, '種子植物が受粉した後、やがて種子となる部分はどれか。', '胚珠', array['子房', '柱頭', 'やく'], '受粉したのち、子房は果実になり、胚珠は種子になる', null),
  ('sci_1_b4_158', '理科', 1, '植物のつくりとはたらき', 2, '植物の呼吸はいつ行われるか。', '一日中。', array['昼間のみ。', '夜間のみ。', '気温が高いときだけ。'], '呼吸によって酸素を吸収し二酸化炭素を吐き出すことは、一日中おこなわれている。ただし植物は日中、光が当たるときは光合成と呼吸の両方を行い、光合成によってできる酸素の量が呼吸で使う酸素より多いので二酸化炭素を吸収して酸素を吐き出している。夜間、光が当たらないと光合成はせず呼吸だけで酸素を吸収し、二酸化炭素を吐き出している。', null),
  ('sci_1_b4_159', '理科', 1, '動物の分類', 2, '鳥類について、なかまのふやしかたはどれか。', '卵生(殻あり)', array['卵生(殻なし)', '胎生', '卵生と胎生の両方'], '鳥類は陸上で卵を産むので乾燥を防ぐために殻がある。鳥類の卵の殻はかたい。', null),
  ('sci_1_b4_160', '理科', 1, '身のまわりの物質', 2, 'ものを作っている材料に注目して区別するとき何と言うか。', '物質', array['物体', '質量', '密度'], 'ものを形や用途に注目して区別すると物体といい、材料に注目して区別すると物質という。', null),
  ('sci_1_b4_161', '理科', 1, '身のまわりの物質', 2, 'プラスチックに当てはまらないものはどれか。', '金属', array['合成樹脂', '有機物', '絶縁体'], 'プラスチックは石油などから人工的に合成された物質で合成樹脂ともいい、有機物である。', null),
  ('sci_1_b4_162', '理科', 1, '光の性質', 2, '空気中から水へ光が入るときの、入射角と屈折角の関係はどれか。', '入射角>屈折角', array['入射角=屈折角', '入射角<屈折角', '光の強さによって変わる'], '境界面に垂直な線と屈折光の角度を屈折角といい、光が空気から水に斜めに進むときは屈折角が小さくなる。逆に水から空気に出るときは屈折角は大きくなる。', null),
  ('sci_1_b4_163', '理科', 1, '音の性質', 2, '音の速さは水中と空気中ではどちらのほうが速いか。', '水中', array['空気中', '同じ', '音の高さによって変わる'], '音の速さは伝わる物質によって異なる。一般に気体より液体、液体より固体のほうが速く伝わる。', null),
  ('sci_1_b4_164', '理科', 1, '火山と火成岩', 2, '地下の高温で岩石がどろどろに溶けた物質を何というか。', 'マグマ', array['プレート', 'コア', '溶岩'], 'プレートが沈み込んでいるところで岩石の一部が溶けてどろどろの物質マグマになる。', null),
  ('sci_1_b4_165', '理科', 1, '火山と火成岩', 2, '次の火成岩のうち、もっとも黒っぽいものはどれか。', '斑れい岩', array['花こう岩', 'せん緑岩', '流紋岩'], '深成岩は、鉱物の違いから白っぽいものから黒っぽいものまである。白い方から順に花こう岩、せん緑岩、斑れい岩である。', null),
  ('sci_1_b4_166', '理科', 1, '火山と火成岩', 2, '次の火成岩のうち、もっとも白っぽいものはどれか。', '流紋岩', array['安山岩', '玄武岩', '斑れい岩'], '火山岩は含まれる鉱物の違いにより白っぽいものから黒っぽいものまで種類がわかれている。 白い方から順に流紋岩、安山岩、玄武岩である。', null),
  ('sci_1_b4_167', '理科', 1, '地層と化石', 2, '川の上流など、流れが急なところで盛んなはたらきはどれか。', '侵食', array['運搬', '堆積', '風化'], '侵食は流水が岩石などをけずりとることであるから、流れが急な上流で盛んである。いっぽう流れがゆるやかなところでは堆積がさかんに行われる。', null),
  ('sci_1_b4_168', '理科', 1, '動物の分類', 2, '魚類について、なかまのふやしかたはどれか。', '卵生(殻なし)', array['卵生(殻あり)', '胎生', '卵生と胎生の両方'], '魚類は水中に卵を産むので、卵に殻はない。', null),
  ('sci_1_b4_169', '理科', 1, '動物の分類', 2, '爬虫類について、なかまのふやしかたはどれか。', '卵生(殻あり)', array['卵生(殻なし)', '胎生', '卵生と胎生の両方'], '爬虫類は陸上に卵を産むので乾燥を防ぐために卵に殻がある。爬虫類の卵の殻は弾力がある。', null),
  ('sci_2_b4_001', '理科', 2, '化学変化と分解', 2, '別名を重曹といい、ベーキングパウダーにも含まれるものはどれか。', '炭酸水素ナトリウム', array['水酸化ナトリウム', '炭酸ナトリウム', '塩化ナトリウム'], '炭酸水素ナトリウムは重曹とも呼ばれ、ケーキ作りにつかうベーキングパウダーにも含まれている。', null),
  ('sci_2_b4_002', '理科', 2, '化学変化と分解', 2, '炭酸水素ナトリウムを分解した時にできる物質として間違いはどれか。', '水素', array['炭酸ナトリウム', '二酸化炭素', '水'], '炭酸水素ナトリウムを加熱すると、炭酸水素ナトリウム→炭酸ナトリウム+水+二酸化炭素という化学反応をおこす。', null),
  ('sci_2_b4_003', '理科', 2, '化学変化と分解', 2, '塩化コバルト紙は何をたしかめるために使うのか。', '水', array['二酸化炭素', 'アルカリ性', '酸性'], 'もとは青色をしている塩化コバルト紙が水に反応すると赤色になる。', null),
  ('sci_2_b4_004', '理科', 2, '化学変化と分解', 2, 'フェノールフタレイン液は何を調べるために使うのか。', 'アルカリ性', array['水', '二酸化炭素', '酸性'], 'もとは無色のフェノールフタレイン溶液はアルカリ性に反応して赤色になる。', null),
  ('sci_2_b4_005', '理科', 2, '化学変化と分解', 2, '炭酸水素ナトリウムの化学式はどれか。', 'NaHCO₃', array['Na₂CO₃', 'COHNa', 'NaCl'], '炭酸水素ナトリウムの化学式はNaHCO₃ である。 Na₂CO₃ は炭酸ナトリウム、NaClは塩化ナトリウムである。', null),
  ('sci_2_b4_006', '理科', 2, '化学変化と分解', 1, '酸化銀の色はどれか。', '黒色', array['白色', '灰色', '黄色'], '酸化銀は黒色、熱分解すると白色の銀の粉末ができる。', null),
  ('sci_2_b4_007', '理科', 2, '化学変化と分解', 2, '単体の金属に共通の性質で間違っているものはどれか。', '磁石につく', array['熱を伝えやすい', '金属光沢がある', 'たたくとのびる'], '単体の金属は、熱を伝えやすく、電気を通しやすく、延性、展性があり、金属光沢がある。磁石につくのは鉄など一部の金属だけである', null),
  ('sci_2_b4_008', '理科', 2, '化学変化と分解', 2, '電気を通しやすいのはどれか。', '銀', array['酸化銀', '水', '酸素'], '銀は金属の単体なので電気を通しやすい。', null),
  ('sci_2_b4_009', '理科', 2, '化学変化と分解', 1, '酸化銀の化学式はどれか。', 'Ag₂O', array['Ag', 'AgO', 'AgO₂'], '酸化銀の化学式はAg₂Oである。', null),
  ('sci_2_b4_010', '理科', 2, '化学変化と分解', 2, '水を電気分解した時に+極から発生する気体について正しいものはどれか。', '過酸化水素水と二酸化マンガンをまぜると発生する', array['石灰水を混ぜると白くにごる', '亜鉛に塩酸を混ぜると発生する', '水に溶けやすい'], '+極からは酸素が発生する。酸素は水に溶けにくい。また1)は二酸化炭素、3)は水素の性質である。', null),
  ('sci_2_b4_011', '理科', 2, '化学変化と分解', 2, '水を電気分解した時に−極から発生する気体について正しいものはどれか。', '最も軽い気体である。', array['空気中の約80%を占める', '刺激臭がある。', 'ものが燃えるのを助ける性質がある。'], '−極から発生するのは水素である。水素は無色無臭で最も軽い気体である。また1)は窒素、3)は酸素の性質である。', null),
  ('sci_2_b4_012', '理科', 2, '化学変化と分解', 2, '水の電気分解の時に少量の水酸化ナトリウムを加えるのはなぜか。', '電気を通しやすくするため。', array['電極を溶かすため。', '発生した気体が水に溶けないようにするため', '加熱を防ぐため。'], '純粋な水は電気を通しにくいため、少量の水酸化ナトリウムまたは硫酸を加える。', null),
  ('sci_2_b4_013', '理科', 2, '化学変化と分解', 1, '塩化銅は何色か。', '青色', array['白色', '赤褐色', '黒色'], '塩化銅は青色である。', null),
  ('sci_2_b4_014', '理科', 2, '化学変化と分解', 1, '銅は何色か。', '赤褐色', array['灰色', '青色', '黒色'], '銅は赤褐色をしている。', null),
  ('sci_2_b4_015', '理科', 2, '化学変化と分解', 2, '塩素の性質として間違っているものはどれか。', '水に溶けにくい', array['刺激臭がある', '黄緑色である', '漂白作用がある'], '塩素は黄緑色の刺激臭のある気体で、空気より重く、水によく溶ける。殺菌作用、漂白作用があり有毒である。', null),
  ('sci_2_b4_016', '理科', 2, '原子と分子', 2, '原子は化学変化によって（　　）。', '分割できない。', array['他の種類に変化する。', '新しく作ることができる。', 'なくなることもある。'], '原子は化学変化でそれ以上分けることができないまた、化学変化で新しくできたり、なくなったり、種類が変化したりしない。', null),
  ('sci_2_b4_017', '理科', 2, '原子と分子', 2, '原子は現在、約何種類発見されているか。', '110', array['10', '30', '1100'], '原子は現在約110種類発見されている。', null),
  ('sci_2_b4_018', '理科', 2, '原子と分子', 2, 'いくつかの原子が結びついた粒子を何というか。', '分子', array['元素', '電子', '中性子'], '原子がいくつか結びついた粒子を分子という。アボガドロが唱えた。分子は物質の性質を示す最小の粒子である。ただし、物質の中には分子をもたないものもある。', null),
  ('sci_2_b4_019', '理科', 2, '原子と分子', 1, '分子を持つものを選べ。', '窒素', array['鉄', '炭素', 'アルミニウム'], '非金属原子の単体や、非金属原子だけでできた化合物は分子をもつ。ただし硫黄や炭素の単体は金属と同じように分子をもたない。', null),
  ('sci_2_b4_020', '理科', 2, '原子と分子', 2, '物質を原子の記号で表したものが（　　）である。', '化学式', array['化学反応式', '元素記号', '物質記号'], '原子の記号を用いて物質の構成を表したのが化学式である。', null),
  ('sci_2_b4_021', '理科', 2, '原子と分子', 1, '単体を選べ。', 'マグネシウム', array['アンモニア', 'エタノール', '塩酸'], '1種類の原子からできている物質を単体という。アンモニアは窒素と水素、エタノールは炭素と水素と酸素、塩酸は塩素と水素でできている。', null),
  ('sci_2_b4_022', '理科', 2, '原子と分子', 1, '化合物を選べ。', '水', array['ナトリウム', '亜鉛', '塩素'], '2種類以上の原子でできている物質を化合物という。水は水素と酸素の2種類の原子でできている。', null),
  ('sci_2_b4_023', '理科', 2, '化学変化と熱', 2, '化学変化によって取り出すことのできるエネルギーを何というか。', '化学エネルギー', array['運動エネルギー', '電気エネルギー', '熱エネルギー'], '化学エネルギーは物質がもともともっているエネルギーで化学変化で取り出すことができる。', null),
  ('sci_2_b4_024', '理科', 2, '化学変化と熱', 2, '化学変化でエネルギーを取り出す場合、もっともよくある形はどれか。', '熱エネルギー', array['電気エネルギー', '原子力エネルギー', '運動エネルギー'], '化学エネルギーを化学変化で取り出す場合、光や熱として取り出すことが多い。', null),
  ('sci_2_b4_025', '理科', 2, '化学変化と熱', 2, '発熱反応では反応前の物質と反応後の物質で化学エネルギーの合計が大きいのはどちらか。', '反応前', array['反応後', '反応前と反応後は同じ', '反応によって様々'], '反応前のエネルギーの大きい物質が、エネルギーを放出して反応後に小さなエネルギーの物質に変わる。このときの放出されるエネルギーが熱なので発熱反応になる。', null),
  ('sci_2_b4_026', '理科', 2, '化学変化と熱', 2, '吸熱反応はどれか。', '塩化アンモニウム+水酸化バリウム→アンモニア+塩化バリウム+水', array['鉄+硫黄→硫化鉄', '銅+酸素→酸化銅', 'マグネシウム+塩酸→塩化マグネシウム+水素'], '塩化アンモニウムと水酸化バリウムからアンモニアができる反応は代表的な吸熱反応である。', null),
  ('sci_2_b4_027', '理科', 2, '化学変化と熱', 2, '簡易冷却パックができるのはどれか。', '炭酸水素ナトリウムとクエン酸をまぜ、水を入れてよく振り混ぜる', array['酸化カルシウムと水を反応させる', '鉄粉と活性炭を封筒に入れ塩化ナトリウム水溶液を入れる', '塩酸と水酸化ナトリウムを混ぜる'], '炭酸水素ナトリウムとクエン酸が反応して二酸化炭素が発生し温度が下がる', null),
  ('sci_2_b4_028', '理科', 2, '酸化と還元', 2, '物質が酸素と結びつく化学変化を何というか。', '酸化', array['還元', '分解', '中和'], '酸化は化合の一種で、物質が酸素と結びつく反応のことである。', null),
  ('sci_2_b4_029', '理科', 2, '酸化と還元', 2, '酸化のうち熱や光を出して激しく反応することを何というか。', '燃焼', array['激化', '融解', '沸騰'], '燃焼は酸化の一種で、熱や光を出して激しく反応することである。', null),
  ('sci_2_b4_030', '理科', 2, '酸化と還元', 2, '次の酸化物のうち白色のものはどれか。', '酸化マグネシウム', array['酸化銀', '酸化銅', '酸化鉄'], '中学校の実験で出てくる酸化物には黒色が多いが、酸化マグネシウムは白色である。', null),
  ('sci_2_b4_031', '理科', 2, '酸化と還元', 2, '酸化物から酸素を取り除く反応を何というか。', '還元', array['化合', '分解', '酸化'], '酸化物から酸素を取り除く反応を還元という。', null),
  ('sci_2_b4_032', '理科', 2, '酸化と還元', 2, '二酸化炭素を還元できる物質はどれか。', 'マグネシウム', array['エタノール', '銅', '鉄'], '炭素よりマグネシウムのほうが酸素と結びつきやすいので、二酸化炭素の中でマグネシウムを燃焼させると二酸化炭素を還元する。', null),
  ('sci_2_b4_033', '理科', 2, '化学変化と物質の質量', 2, '密閉しない容器で実験をおこなった場合、容器内の質量が実験前より実験後のほうが減少するのはどれか。', 'うすい塩酸に炭酸水素ナトリウムを加える', array['うすい硫酸とうすい水酸化バリウムを混ぜる', '銅の粉末を加熱する', '鉄と硫黄の粉末を混ぜて加熱する'], '気体が発生して容器の外へ逃げる実験では、その分だけ質量が減少する。うすい塩酸に炭酸水素ナトリウムを加えると二酸化炭素が発生するため減少する。硫酸と水酸化バリウム、鉄と硫黄では気体が発生せず質量は変わらず、銅の加熱では空気中の酸素と化合する分だけ増える。', null),
  ('sci_2_b4_034', '理科', 2, '化学変化と物質の質量', 2, '質量保存の法則はどれか。', '化学変化の前後で、反応に関係している物質全体の質量は変化しない', array['原子は化学変化によってそれ以上わけることはできない。', '化学変化に関する物質の質量比は一定である', 'エネルギーはいろいろな形に変化するが、その総量は変化しない'], '「化学変化の前後で、反応に関係している物質全体の質量は変化しない 」これを質量保存の法則という。このため、密閉した容器で実験を行うと実験の前後で質量は同じになる。', null),
  ('sci_2_b4_035', '理科', 2, '化学変化と物質の質量', 2, '質量保存の法則が成り立つのはなぜか。', '化学変化では物質を構成する原子の組み合わせが変わるが、原子の種類と数は変わらないから。', array['物質の持つ化学エネルギーは化学変化によって熱エネルギーになって発生するから', '化学変化では物質そのものは変化しないから。', '化学変化とはフロギストンが失われることによっておこる現象だから'], '化学変化は、物質がまったく違う物質に変わってしまう反応であるが、それは物質を構成する原子の組み合わせが変わるためである。原子は化学変化でなくなったり、新たに出来たり、種類や質量が変化しないので、化学変化の前後で全体の質量は変化しない。', null),
  ('sci_2_b4_036', '理科', 2, '化学変化と物質の質量', 2, '化学変化に関係する物質の質量比は（　　）。', '常に一定である', array['常に変化する', '必ず1：1になる', '必ず1:4になる'], '化学変化に関係する物質の質量比は常に一定になる。例・・・銅：酸素=4:1、 マグネシウム:酸素=3:2', null),
  ('sci_2_b4_037', '理科', 2, '細胞のつくり', 2, '核を染める染色液はどれか。', '酢酸オルセイン溶液', array['BTB溶液', 'フェノールフタレイン溶液', 'ヨウ素液'], '核は酢酸オルセイン溶液、酢酸カーミン溶液、酢酸ダーリア溶液などによく染まる。', null),
  ('sci_2_b4_038', '理科', 2, '細胞のつくり', 2, '動物の細胞にはほとんどなくて、おもに植物の細胞にあるつくりはどれか。', '液胞', array['細胞膜', '核', '細胞質'], '液胞は主に植物の細胞にみられ、細胞の活動によって生じた不要物や、色素などが入っている。', null),
  ('sci_2_b4_039', '理科', 2, '細胞のつくり', 1, '細胞壁の役割は何か。', '体を支える', array['光合成をする', '細胞呼吸をする', '不要物を貯める'], '細胞壁は植物の細胞にだけ見られるつくりで、細胞膜の外側にある丈夫な壁である。植物の体を支える役割がある。', null),
  ('sci_2_b4_040', '理科', 2, '細胞のつくり', 2, '単細胞生物ではないものはどれか。', 'ミジンコ', array['ミドリムシ', 'ゾウリムシ', 'ケイソウ'], '単細胞生物とは1つの細胞だけで出来ている生物のことである。ゾウリムシ、ミドリムシ、アメーバ、ケイソウ、ミカヅキモなどがある。ミジンコは多細胞生物の甲殻類である。', null),
  ('sci_2_b4_041', '理科', 2, '細胞のつくり', 2, '多細胞生物で、形やはたらきの同じ細胞が集まったものを何というか。', '組織', array['器官', '内臓', '個体'], '多細胞生物の体内で、形やはたらきの同じ細胞の集まりを組織という。いくつかの組織が集まって一定の形を持ち特定のはたらきをするものが器官である。', null),
  ('sci_2_b4_042', '理科', 2, '排出', 2, '細胞でできたアンモニアは血液によってどの器官におくられるか。', '肝臓', array['ぼうこう', '腎臓', '肺'], 'アンモニアは有害なので、血液によって肝臓に送られて害の少ない尿素にかえられる。', null),
  ('sci_2_b4_043', '理科', 2, '排出', 2, '腎臓のはたらきで間違っているものはどれか。', '血液中のアンモニアを尿素に変える。', array['血液中から余分な塩分をこしとる', '血液中から尿素などの不要物をこしとる', '血液中の無機物の濃度を一定に保つ。'], '腎臓では血液中の尿素などの不要物をこしとるほか、余分な水分、無機物(塩分)をこしとり、血液中の無機物の濃度を一定に保っている。', null),
  ('sci_2_b4_044', '理科', 2, '排出', 2, '尿は腎臓からぼうこうへ（　　）を通って送られる。', '輸尿管', array['血管', 'リンパ管', '消化管'], '腎臓でこしとられた尿素や塩分、水分は尿として、輸尿管を通ってぼうこうへ送られる。', null),
  ('sci_2_b4_045', '理科', 2, '排出', 2, '血液中の不要物は尿以外に（　　）として排出される。', '汗', array['大便', '組織液', '血液'], '血液中の不要物は尿以外に、汗として汗腺から排出される。ただし、汗と尿の成分は似ているが汗のほうがずっとうすい。', null),
  ('sci_2_b4_046', '理科', 2, '排出', 2, '分解されたときにアンモニアが発生するのはどれか。', 'タンパク質', array['デンプン', '脂肪', 'ビタミン'], 'デンプン、脂肪、タンパク質はどれも有機物なので分解したときに二酸化炭素や水が発生するが、タンパク質には窒素も含まれているためタンパク質を分解するとアンモニアが発生する。', null),
  ('sci_2_b4_047', '理科', 2, '消化と吸収', 2, '体に取り入れた食物が吸収されやすいように分解することを何というか。', '消化', array['呼吸', '食事', '循環'], '食物を、吸収しやすいように酵素のはたらきなどで化学変化をおこし、小さな分子に分解することが消化である。', null),
  ('sci_2_b4_048', '理科', 2, '消化と吸収', 2, '糖をしらべる薬品は何か。', 'ベネジクト溶液', array['フェノールフタレイン溶液', '酢酸カーミン溶液', 'BTB溶液'], 'ベネジクト溶液は麦芽糖やブドウ糖などを調べる溶液である。はじめは青色の液体で麦芽糖やブドウ糖の水溶液に加えて沸騰させると赤褐色の沈殿が生じる。', null),
  ('sci_2_b4_049', '理科', 2, '消化と吸収', 2, 'デンプンを調べる薬品は何か。', 'ヨウ素液', array['フェノールフタレイン溶液', '石灰水', '酢酸オルセイン溶液'], 'ヨウ素液はデンプンを調べる薬品である。はじめは茶色で、デンプンにくわえると青紫色に変化する。', null),
  ('sci_2_b4_050', '理科', 2, '消化と吸収', 2, '消化管の一部として正しくない器官はどれか。', '肝臓', array['食道', '胃', '小腸'], '口から食道、胃、小腸、大腸、肛門へとつながる1本の管を消化管という。肝臓は消化に関係する重要な器官だが消化管ではない', null),
  ('sci_2_b4_051', '理科', 2, '消化と吸収', 2, '唾液に含まれる消化酵素はなにか。', 'アミラーゼ', array['トリプシン', 'リパーゼ', 'ペプシン'], '唾液は唾液腺から分泌される消化液でアミラーゼを含み、デンプンを分解して糖(麦芽糖)に変える。', null),
  ('sci_2_b4_052', '理科', 2, '消化と吸収', 2, '胃液に含まれる消化酵素は何か。', 'ペプシン', array['アミラーゼ', 'トリプシン', 'リパーゼ'], '胃液は胃から分泌される消化液でペプシンを含み、タンパク質を分解する。', null),
  ('sci_2_b4_053', '理科', 2, '消化と吸収', 2, 'すい液には含まれていない消化酵素はどれか。', 'ペプシン', array['アミラーゼ', 'トリプシン', 'リパーゼ'], 'すい液はすい臓から分泌される消化液で、アミラーゼやトリプシン、リパーゼなどを含みタンパク質、脂肪、デンプンなどを分解する。', null),
  ('sci_2_b4_054', '理科', 2, '消化と吸収', 2, '胆汁はどの器官で作られるか。', '肝臓', array['胃', '胆のう', '小腸'], '胆汁は肝臓で作られ、胆のうに貯められる。胆汁には消化酵素は含まれず、脂肪の消化を助けるはたらきがある。', null),
  ('sci_2_b4_055', '理科', 2, '消化と吸収', 2, '消化酵素の性質で間違っているものはどれか。', '消化酵素自身が化学変化する。', array['体温に近い温度でよくはたらく', '分解する物質が決まっている。', '少量でたくさん分解できる。'], '消化酵素は栄養分を分解する触媒のはたらきをする。自分自身は変化しないので少量でたくさん分解できる。体温に近い温度でよくはたらき種類ごとに分解する物質が決まっている。', null),
  ('sci_2_b4_056', '理科', 2, '消化と吸収', 2, 'デンプンが消化されて、最終的に吸収されるとき何という物質になっているか。', 'ブドウ糖', array['麦芽糖', 'アミノ酸', 'モノグリセリド'], 'デンプンはアミラーゼにより分解されて麦芽糖になり、さらに分解され最終的にはブドウ糖になって小腸の柔毛から吸収される。', null),
  ('sci_2_b4_057', '理科', 2, '消化と吸収', 2, 'タンパク質が消化されて、最終的に何という物質になるか。', 'アミノ酸', array['ブドウ糖', 'モノグリセリド', '脂肪酸'], 'タンパク質は胃液、すい液、小腸の壁の酵素により分解され、最終的にアミノ酸となって小腸の柔毛から吸収される。', null),
  ('sci_2_b4_058', '理科', 2, '消化と吸収', 2, '脂肪を分解する消化酵素はどれか。', 'リパーゼ', array['アミラーゼ', 'ペプシン', 'トリプシン'], '脂肪はリパーゼによって分解される。リパーゼは主にすい液に含まれている。', null),
  ('sci_2_b4_059', '理科', 2, '消化と吸収', 2, 'デンプンを分解する消化酵素はどれか。', 'アミラーゼ', array['ペプシン', 'トリプシン', 'リパーゼ'], 'デンプンは唾液やすい液に含まれるアミラーゼによって分解され麦芽糖になる。さらに小腸の壁の酵素で最終的にブドウ糖に分解される。', null),
  ('sci_2_b4_060', '理科', 2, '消化と吸収', 2, '小腸の壁にはたくさんのひだがあり、その表面に（　　）という小さい突起がたくさんある。', '柔毛', array['根毛', '肺胞', '腸毛'], '栄養分が消化され、ブドウ糖、アミノ酸、脂肪酸、モノグリセリドとなり小腸の壁の柔毛から吸収される。柔毛は小さくてたくさんあるので表面積が大きくなり栄養分が効率よく吸収される。', null),
  ('sci_2_b4_061', '理科', 2, '消化と吸収', 2, 'ブドウ糖とアミノ酸が吸収されるのはどれか。', '毛細血管', array['リンパ管', '輸尿管', '師管'], 'ブドウ糖とアミノ酸は柔毛の中の毛細血管に吸収される。', null),
  ('sci_2_b4_062', '理科', 2, '消化と吸収', 2, '脂肪が吸収されるのはどれか。', 'リンパ管', array['毛細血管', '輸尿管', '師管'], '脂肪酸とモノグリセリドは柔毛に吸収されたあと、脂肪に戻ってリンパ管に吸収される。', null),
  ('sci_2_b4_063', '理科', 2, '消化と吸収', 2, 'ブドウ糖とアミノ酸は小腸で吸収されたあとどの器官に運ばれるか。', '肝臓', array['胃', '肺', '腎臓'], 'ブドウ糖とアミノ酸は柔毛の毛細血管に吸収され、肝臓へ送られる。そこで全身に送られたり、別の物質に変えられたり、たくわえられたりする。', null),
  ('sci_2_b4_064', '理科', 2, '消化と吸収', 1, '大腸のはたらきはどれか。', '水分の吸収', array['栄養分を貯える', '不要物をこしとる', '二酸化炭素の排出'], '大腸では小腸で吸収しきれなかった水分を吸収する。', null),
  ('sci_2_b4_065', '理科', 2, '消化と吸収', 2, '栄養分を吸収する器官はどれか。', '小腸', array['口', 'すい臓', '肝臓'], '消化された栄養分は主に小腸から吸収される。', null),
  ('sci_2_b4_066', '理科', 2, '消化と吸収', 2, '有害なものを無害に変える器官はどれか。', '肝臓', array['腎臓', '小腸', '肺'], '肝臓には多くのはたらきがあり、その1つに有害なものを無害に変えるはたらきがある。', null),
  ('sci_2_b4_067', '理科', 2, '消化と吸収', 2, '胆汁をたくわえる器官はどれか。', '胆のう', array['肝臓', '小腸', '大腸'], '胆汁は肝臓でつくられて胆のうにたくわえられ、食事時にでてきて脂肪の消化をたすける。', null),
  ('sci_2_b4_068', '理科', 2, '消化と吸収', 2, '栄養分を貯えたり、他の物質に変えたりする器官はどれか。', '肝臓', array['小腸', '腎臓', 'すい臓'], '小腸で吸収されたアミノ酸とブドウ糖は肝臓に運ばれ、そこから全身に送られる以外に、他の物質につくりかえられたり、貯えられたりする。', null),
  ('sci_2_b4_069', '理科', 2, '消化と吸収', 2, 'アンモニアを尿素に変える器官はどれか。', '肝臓', array['腎臓', '小腸', '大腸'], '細胞呼吸によって発生したアンモニアは血液によって肝臓に運ばれ、そこで尿素につくり変えられる。', null),
  ('sci_2_b4_070', '理科', 2, '消化と吸収', 1, '胆汁をつくる器官はどれか。', '肝臓', array['胆のう', 'すい臓', '小腸'], '胆汁は肝臓でつくられ、胆のうにたくわえられる。', null),
  ('sci_2_b4_071', '理科', 2, '呼吸', 2, '細胞呼吸では栄養分を（　　）によって分解している。', '酸素', array['二酸化炭素', '酵素', '水'], '小腸から吸収した栄養分(有機養分)を酸素を使って分解してエネルギーを得ることが細胞呼吸である。これは有機物の酸化と同じ化学変化なので二酸化炭素と水がでる。', null),
  ('sci_2_b4_072', '理科', 2, '呼吸', 2, '細胞呼吸によって生物は、生きるために必要な（　　）を得ている。', 'エネルギー', array['栄養分', '水', '血液'], '細胞呼吸の目的はエネルギーを得ることである。', null),
  ('sci_2_b4_073', '理科', 2, '呼吸', 2, '肺では酸素を取り入れ、（　　）を排出している。', '二酸化炭素', array['窒素', 'アンモニア', '水'], '細胞呼吸で出た二酸化炭素は不要物なので、各細胞から血液によって肺まで運ばれ排出される。', null),
  ('sci_2_b4_074', '理科', 2, '呼吸', 2, '肺には筋肉がないので、ろっ骨が上がり、（　　）が下がって胸腔が広がり空気を吸うことができる。', '横隔膜', array['肺胞', '網膜', '脊椎'], '肺には筋肉がないので、胸腔を広げるために、横隔膜という筋肉が下がり、ろっ骨の筋肉がろっ骨を上げる。胸腔を狭めるときはその逆になる。', null),
  ('sci_2_b4_075', '理科', 2, '呼吸', 2, '肺胞とは（　　）の先にある小さな袋のことである。', '気管支', array['食道', '血管', 'リンパ管'], '鼻や口から入った空気は気管を通り、肺に入る。肺は気管支とその先にある肺胞という小さな袋でできている。', null),
  ('sci_2_b4_076', '理科', 2, '呼吸', 2, '肺胞の周りには（　　）が網の目状にとりまいている。', '毛細血管', array['リンパ管', '消化管', '道管'], '肺胞の周りには網の目状に毛細血管が取り巻き、酸素を血液に取り込み、二酸化炭素を排出している。', null),
  ('sci_2_b4_077', '理科', 2, '呼吸', 2, '肺胞が小さくたくさんあることで（　　）が大きくなり気体の交換が効率よく行える。', '表面積', array['質量', '細胞', '体積'], '肺胞は小さく、たくさんあるので肺の内部の表面積が大きくなる。', null),
  ('sci_2_b4_078', '理科', 2, '血液の循環', 2, '酸素を運ぶ役割の血液の成分は何か。', '赤血球', array['白血球', '血小板', '血しょう'], '赤血球は血液の固形成分の1つで、赤血球内のヘモグロビンのはたらきによって酸素を運んでいる。', null),
  ('sci_2_b4_079', '理科', 2, '血液の循環', 2, '酸素が多いところで酸素と結びつき、酸素が少ないところでは酸素をはなす性質の色素はどれか。', 'ヘモグロビン', array['葉緑体', 'モノグリセリド', 'リンパ'], 'ヘモグロビンは赤血球に含まれる赤い色素で、酸素を運ぶための重要なやくわりをになっている。', null),
  ('sci_2_b4_080', '理科', 2, '血液の循環', 2, '体内に入ったウイルスや細菌などを分解する役割の血液の成分は何か。', '白血球', array['赤血球', '血小板', '血しょう'], '白血球は血液の固形成分の1つでいくつかの種類があり、細菌やウイルスを分解するはたらきがある。', null),
  ('sci_2_b4_081', '理科', 2, '血液の循環', 2, '出血したときに血を固める役割の血液の成分は何か。', '血小板', array['赤血球', '白血球', '血しょう'], '血小板は血液の固形成分のひとつで、血液を固めるはたらきがある。', null),
  ('sci_2_b4_082', '理科', 2, '血液の循環', 2, '組織液とは（　　）が毛細血管の壁からしみだして細胞を浸しているものである。', '血しょう', array['赤血球', '白血球', '血小板'], '血しょうが毛細血管の壁からしみだし細胞の間をひたしている液体が組織液である。', null),
  ('sci_2_b4_083', '理科', 2, '血液の循環', 1, '組織液の役割は何か。', '仲介', array['呼吸', '分解', '吸収'], '組織液は血液と細胞の間で物質の受け渡しの仲介をしている。', null),
  ('sci_2_b4_084', '理科', 2, '血液の循環', 1, '血液の役割は何か。', '物質の運搬', array['物質の吸収', '物質の分解', 'エネルギーの生成'], '血液は血管の中を流れて体じゅうを循環し、酸素や栄養分、不要物などを運ぶ役割をになっている。', null),
  ('sci_2_b4_085', '理科', 2, '血液の循環', 2, '心臓の役割は何か。', 'ポンプのやくわり', array['呼吸をする', 'エネルギーを作り出す', '不要物を排出する'], '心臓は血液を循環させるポンプのやくわりをになっている。', null),
  ('sci_2_b4_086', '理科', 2, '血液の循環', 2, '心臓の筋肉が周期的に収縮することを（　　）という。', '拍動', array['呼吸', 'ぜん動', '振動'], '心臓は筋肉が周期的に収縮して血液の流れを作っている。これを拍動という。', null),
  ('sci_2_b4_087', '理科', 2, '血液の循環', 2, '心臓から出て行く血液が流れる血管を何というか。', '動脈', array['静脈', '毛細血管', '門脈'], '動脈とは心臓から出て行く血液が流れる血管のことである。高い圧力に耐えられるように血管の壁は厚く、弾力がある。', null),
  ('sci_2_b4_088', '理科', 2, '血液の循環', 2, '心臓に戻ってくる血液が流れる血管を何というか。', '静脈', array['動脈', '毛細血管', '門脈'], '静脈とは心臓に戻ってくる血液が流れる血管のことである。動脈より壁がうすく、逆流を防ぐための弁がある。', null),
  ('sci_2_b4_089', '理科', 2, '血液の循環', 2, '全身に網の目状に分布する末端の血管を何というか。', '毛細血管', array['動脈', '静脈', '門脈'], '毛細血管とは、末端の最も細い血管のことで、全身に網目状に分布している。毛細血管の壁をとおして物質のやりとりが行われる。', null),
  ('sci_2_b4_090', '理科', 2, '血液の循環', 2, '酸素の多い血液を何というか。', '動脈血', array['赤血', '静脈血', '鮮血'], '動脈血とは酸素を多く含んだ血液で、肺動脈以外の全ての動脈と肺静脈に流れている。鮮やかな赤い色をしている。', null),
  ('sci_2_b4_091', '理科', 2, '血液の循環', 2, '酸素の少ない血液を何というか。', '静脈血', array['黒血', '動脈血', '鮮血'], '静脈血とは酸素を受け渡した後の、酸素が少ない血液のことである。肺静脈以外のすべての静脈と肺動脈に流れている。黒っぽい色をしている。', null),
  ('sci_2_b4_092', '理科', 2, '刺激と反応', 2, '外界からの刺激を受け取る器官を何というか。', '感覚器官', array['運動器官', '消化器官', '相同器官'], '外界から刺激を受け取る器官を感覚器官という。ヒトの感覚器官は目、耳、舌、鼻、皮膚の5つである。', null),
  ('sci_2_b4_093', '理科', 2, '刺激と反応', 2, '外界からの刺激を受け取る細胞を何というか。', '感覚細胞', array['神経細胞', '刺激細胞', '筋細胞'], '感覚器官にはそれぞれの刺激を受け取る感覚細胞が集まっており、受け取った刺激は神経を通り脳におくられる。', null),
  ('sci_2_b4_094', '理科', 2, '刺激と反応', 2, '皮膚で受け取る刺激のうち間違っているのはどれか。', '音', array['熱さ', '冷たさ', '痛み'], '皮膚の表面には熱さ、冷たさ、痛み、圧力などの刺激を受け取る感覚点が分布している。', null),
  ('sci_2_b4_095', '理科', 2, '刺激と反応', 2, '目で、感覚細胞がある部分を何というか。', '網膜', array['レンズ', '視神経', '虹彩'], '目は物体からの光をレンズで屈折させ、網膜の上に像を結ぶ。網膜上には感覚細胞があり、光の刺激を信号に変えて視神経を通って脳に伝えられる。', null),
  ('sci_2_b4_096', '理科', 2, '刺激と反応', 2, '耳で感覚細胞がある部分を何というか。', 'うずまき管', array['鼓膜', '聴神経', '耳小骨'], '鼓膜が音を捉えて振動し、その振動を耳小骨がうずまき管の液体に伝える。うずまき管の感覚細胞が振動の刺激を信号に変えて聴神経を通って脳に伝えられる。', null),
  ('sci_2_b4_097', '理科', 2, '刺激と反応', 2, '魚にある側線はどんな刺激を受け取る器官か。', '水圧', array['光', 'におい', '音'], '魚の側線は水圧や水流の向きを感じ取る感覚器官である。', null),
  ('sci_2_b4_098', '理科', 2, '刺激と反応', 2, '筋肉は骨についているものだけでなく（　　）にもある。', '内臓', array['脳', '神経', '肺'], '筋肉には骨につく骨格筋と内臓壁をつくる内臓筋がある。', null),
  ('sci_2_b4_099', '理科', 2, '刺激と反応', 2, '骨格は体を支えるとともに脳などの神経や内臓を（　　）役割もある。', '保護する', array['動かす', 'きたえる', '増やす'], '頭骨は脳を保護し、ろっ骨は胸郭を形作って肺や心臓などを保護し、背骨は脊髄を保護している。', null),
  ('sci_2_b4_100', '理科', 2, '刺激と反応', 1, '脳や脊髄を何というか。', '中枢神経', array['末梢神経', '自律神経', '知覚神経'], '脳や脊髄は多くの神経が集まって判断や命令を行う場所なので中枢神経とよばれる。中枢神経から枝分かれして全身に広がる神経が末梢神経である。', null),
  ('sci_2_b4_101', '理科', 2, '刺激と反応', 2, '感覚器官からの信号を脳や脊髄に伝える神経を何というか。', '感覚神経', array['交感神経', '副交感神経', '運動神経'], '感覚神経は末梢神経の一つで、感覚器官で受け取った刺激が感覚細胞で信号に変えられ、その信号を中枢神経に伝える。', null),
  ('sci_2_b4_102', '理科', 2, '刺激と反応', 2, '脳や脊髄からの命令を内臓や運動器官に伝える神経を何というか。', '運動神経', array['知覚神経', '自律神経', '迷走神経'], '運動神経は末梢神経の一つで、中枢神経からの命令を内臓や運動器官に伝える。', null),
  ('sci_2_b4_103', '理科', 2, '刺激と反応', 2, '脳や脊髄は（　　）によって守られている。', '骨', array['筋肉', '血液', '組織液'], '脳は頭骨に、脊髄は背骨に守られている。', null),
  ('sci_2_b4_104', '理科', 2, '刺激と反応', 2, '刺激に対して無意識に起こる、生まれつき持っている反応を何というか。', '反射', array['直接反応', '間接反応', '伝達'], '意識して起こす反応は脳が命令を出しているが、反射は脳に伝わる前の脊髄などで命令が出されるので短い時間で反応できる。反射は危険から身を守ったり、体のはたらきを調節したりするのに役立つ。', null),
  ('sci_2_b4_105', '理科', 2, '圧力', 2, '圧力を計算するには、ある面に垂直にはたらく力を（　　）で割る。', '面積', array['体積', '質量', '重さ'], '圧力とは単位面積に垂直にはたらく力のことである。圧力=力÷面積で計算する。', null),
  ('sci_2_b4_106', '理科', 2, '圧力', 3, '長さ1mをcmに直すといくつか。', '100cm', array['10cm', '1000cm', '10000cm'], '1m=100cm', null),
  ('sci_2_b4_107', '理科', 2, '圧力', 3, '面積1m²をcm²に直すといくつか。', '10000cm²', array['10cm²', '100cm²', '1000cm²'], '1m×1m=1m²で、これをcmにすると100cm×100cm=10000cm²なので1m²=10000cm²となる。', null),
  ('sci_2_b4_108', '理科', 2, '圧力', 3, '3m²の面積に6Nの力がかかっているときの圧力はいくつか。', '2Pa', array['0.5Pa', '18Pa', '0.2Pa'], '圧力[Pa]=力[N]÷面積[m²]なので6÷3=2となる', null),
  ('sci_2_b4_109', '理科', 2, '空気中の水蒸気', 2, '雲について間違っているものはどれか。', '水蒸気', array['水滴', '氷の粒', '上空にできる'], '雲は上空に浮かんだ水滴や氷の粒である。', null),
  ('sci_2_b4_110', '理科', 2, '空気中の水蒸気', 2, '霧のでき方はどれか。', '放射冷却などで地面の温度が下がり、地表付近の空気が冷やされて水滴ができる。', array['空気が下降して空気が膨張し、膨張すると気温が下がるので地表付近で水滴ができる。', '雨が地面に跳ね返って非常に小さな水滴となって地表付近に浮かぶ', '上空の雲が下降気流によって地表付近に押し下げられる'], '放射冷却などで地面の温度が下がり、それによって地表付近の空気の温度が下がり、気温が露点より低くなると飽和水蒸気量を超えた水蒸気が水滴になる。', null),
  ('sci_2_b4_111', '理科', 2, '空気中の水蒸気', 2, '上空と地表で、気圧が低いのはどちらか。', '上空', array['地表', '同じ', 'どちらともいえない'], '気圧とは単位面積にかかる空気の重さなので、地表より上空のほうが低くなる。', null),
  ('sci_2_b4_112', '理科', 2, '空気中の水蒸気', 2, '空気は膨張すると気温はどうなるか。', '下がる', array['上がる', '同じ', 'どちらともいえない'], '空気が膨張すると気温が下がる。', null),
  ('sci_2_b4_113', '理科', 2, '空気中の水蒸気', 2, '暖かい空気と冷たい空気ではどちらのほうが密度が低いか。', '暖かい空気', array['冷たい空気', '同じ', 'どちらともいえない'], '空気は温度が高いほど密度は小さい。', null),
  ('sci_2_b4_114', '理科', 2, '空気中の水蒸気', 2, '空気が上昇する理由で間違っているのはどれか。', '水が蒸発する', array['風が山にぶつかる', '強い日差しに暖められる', '暖かい空気と冷たい空気がぶつかる'], '空気は暖かいほうが密度が低いので軽い。そのため、夏の強い日差しに暖められたりして温度があがると上昇する。また、暖かい空気と冷たい空気がぶつかると暖かい空気のほうが押し上げられる。その他に、風が山などにぶつかって上昇する。', null),
  ('sci_2_b4_115', '理科', 2, '空気中の水蒸気', 2, 'ナベなどで水を加熱したときに出てくる、白い湯気はどれか。', '液体の水', array['気体の水', '固体の水', '空気'], '水を加熱すると水面から水蒸気(気体の水)が出ていき、それが空気で冷やされて液体（小さな水滴)となったのが湯気である。水蒸気は目に見えないので間違わないように。', null),
  ('sci_2_b4_116', '理科', 2, '空気中の水蒸気', 2, '飽和水蒸気量とは何か。', '空気1m³中に含むことのできる最大の水蒸気の量', array['空気1m³から出てくる水蒸気の量', '空気1m³に存在する水蒸気の量', '水蒸気が限界まで含まれた状態の空気'], '水は蒸発すると気体の水蒸気となって空気の中に入っていく。空気に含むことのできる水蒸気の量は決まっていて、 空気1m³に含むことのできる最大の水蒸気の量を飽和水蒸気量という。', null),
  ('sci_2_b4_117', '理科', 2, '空気中の水蒸気', 2, '飽和水蒸気量は気温が高くなるとどう変化するか。', '大きくなる', array['変化しない', '小さくなる', '不安定になる'], '空気は気温が高いほど水蒸気を含みやすくなるので、気温が高くなると飽和水蒸気量は大きくなる。', null),
  ('sci_2_b4_118', '理科', 2, '空気中の水蒸気', 2, '露点とは何か。', '水蒸気を含んだ空気の気温を下げた時に水滴のでき始める温度', array['水蒸気を含んだ空気の気温を上げた時の限界の水蒸気の量', '水蒸気を含んだ空気の気温を下げた時の限界の水蒸気の量', '水蒸気を含んだ空気の気温を上げた時に水滴のでき始める温度'], '飽和水蒸気量は気温が下がるほど小さくなるので、水蒸気を含んだ空気の気温が下がると、水蒸気量が限界を超えてしまう。限界を超えると空気中に水蒸気としていられないので、水滴となって出てくる。水滴のできはじめる温度を露点という。', null),
  ('sci_2_b4_119', '理科', 2, '空気中の水蒸気', 2, '湿度とは何か。', '飽和水蒸気量に対する空気中の水蒸気の割合', array['空気1m³に含まれる水蒸気の量', '空気の重さに対する水蒸気の重さの割合', '現在の空気の温度に対する露点'], '空気中の水蒸気量が、飽和水蒸気量に対してどれだけの割合かを%で表したものを湿度といい、空気がどれくらい湿っているかを示す。', null),
  ('sci_2_b4_120', '理科', 2, '空気中の水蒸気', 2, '最も湿度が高いのはどれか。', '気温25℃、露点20℃', array['気温30℃、露点20℃', '気温30℃、露点10℃', '気温35℃、露点5℃'], '空気中の水蒸気量が、飽和水蒸気量に対してどれだけの割合かを%で表したのが湿度である。露点が高いほど空気中の水蒸気は大きくなり、気温が高いほど飽和水蒸気量が大きくなる。そのため、もっとも気温が低く、もっとも露点が高い(3)の湿度が最も高くなる。ちなみにもっとも湿度が低いのは(4)である。', null),
  ('sci_2_b4_121', '理科', 2, '日本の天気', 2, 'シベリア気団の性質はどれか。', '冷たく、乾いている', array['冷たく、湿っている', '暖かく、湿っている', '暖かく、乾いている'], 'シベリア気団は陸上で、北にあるので冷たく、乾いている。', null),
  ('sci_2_b4_122', '理科', 2, '日本の天気', 2, '日本の冬の典型的な冬型の気圧配置はどれか。', '西高東低', array['南高北低', '東高西低', '北高南低'], '冬にはシベリア気団の高気圧が発達し、北海道の東の海上に低気圧が発達して西高東低の冬型の気圧配置となる。', null),
  ('sci_2_b4_123', '理科', 2, '日本の天気', 2, '日本の冬の季節風の風向きはどれか。', '北西', array['南東', '南西', '北東'], '日本の冬はシベリア気団の高気圧から北西の季節風が吹き付ける。', null),
  ('sci_2_b4_124', '理科', 2, '日本の天気', 2, '春や秋には（　　）の影響で移動性高気圧と低気圧が日本付近を交互に通過するため4〜7日周期で天気が変わる。', '偏西風', array['季節風', '小笠原気団', 'オホーツク海気団'], '春や秋にはそれまで発達していた気団がおとろえて、季節風がよわまり偏西風の影響を受けて移動性高気圧と低気圧が日本付近を交互に通過するようになる。', null),
  ('sci_2_b4_125', '理科', 2, '日本の天気', 2, '梅雨前線などの停滞前線は何気団と何気団がぶつかってできるのか。', 'オホーツク海気団と小笠原気団', array['シベリア気団と小笠原気団', 'シベリア気団とオホーツク海気団', 'シベリア気団とオホーツク海気団と小笠原気団'], '6月ごろオホーツク海気団の高気圧と小笠原気団の高気圧が発達してぶつかり合う。2つがほぼ同じ勢力のため日本付近に停滞前線ができ、この時期を梅雨という。', null),
  ('sci_2_b4_126', '理科', 2, '日本の天気', 2, '湿った風が山を超えて吹くとき、風下側の山麓で急に気温が上がり、乾燥する現象を何というか。', 'フェーン現象', array['熱帯夜', 'ヒートアイランド現象', 'ドーナツ化現象'], '水は蒸発するときには回りの熱を奪い、逆に水蒸気が液体の水になる時には回りに熱を与える。湿った空気が上昇すると水蒸気が雲になるが、このとき回りに熱をあたえるのでこの空気が山を超えて吹き下ろすと風上より風下の気温が上昇する。これをフェーン現象という。', null),
  ('sci_2_b4_127', '理科', 2, '日本の天気', 2, '7月下旬になると（　　）が勢力を強めて張り出し、梅雨が明けると本格的な夏を迎える。', '小笠原気団', array['オホーツク海気団', 'シベリア気団', '偏西風'], '梅雨の時期に同じ勢力だったオホーツク海気団と小笠原気団だが、7月下旬ごろになるとオホーツク海気団の勢力が弱まり小笠原気団の勢力が強まって梅雨明けをむかえる。', null),
  ('sci_2_b4_128', '理科', 2, '日本の天気', 2, '日本の夏の気圧配置はどれか。', '南高北低', array['西高東低', '東高西低', '北高南低'], '小笠原気団の高気圧は日本の南の海上にあって日本付近に張り出し、低気圧が北に押しやられるので南高北低の気圧配置となる。', null),
  ('sci_2_b4_129', '理科', 2, '日本の天気', 2, '日本の夏の季節風の風向きはどれか。', '南東', array['南西', '北東', '北西'], '日本夏は南の海上にある小笠原気団の高気圧から暖かく湿った南東の季節風が吹く。', null),
  ('sci_2_b4_130', '理科', 2, '日本の天気', 2, '夏に夕立のようなにわか雨を降らせる雲はどれか。', '積乱雲', array['乱層雲', '高積雲', '高層雲'], '夏の昼に大気が局地的に熱せられ上昇気流を生じて積乱雲が発達し夕立などのにわか雨を降らせる。', null),
  ('sci_2_b4_131', '理科', 2, '日本の天気', 2, '9月頃から日本付近にできる停滞前線を何というか。', '秋雨前線', array['梅雨前線', '温暖前線', '寒冷前線'], '9月ごろ小笠原気団がおとろえると梅雨の時期と同じような気圧配置になり停滞前線ができる。この時期を秋雨といい、この停滞前線を秋雨前線と呼ぶ。', null),
  ('sci_2_b4_132', '理科', 2, '日本の天気', 2, '（　　）は熱帯地方で発生した低気圧が暖かい海からの水蒸気からエネルギーを得て発達したものである。', '台風', array['前線', '竜巻', 'つむじ風'], '熱帯低気圧のうち風速が17.2m/s以上に発達したものが台風である。南のあたたかい海で水蒸気を吸い上げ、上昇気流によって水蒸気が水滴になる時に熱エネルギーが供給され発達する。', null),
  ('sci_2_b4_133', '理科', 2, '日本の天気', 2, '日本付近の上空に1年中吹く西よりの風を何というか。', '偏西風', array['貿易風', '季節風', '極東風'], '地球規模の大気の動きの中で、日本などがある中緯度地方を南北に蛇行しながら西から東へ地球を一周しているのが偏西風である。', null),
  ('sci_2_b4_134', '理科', 2, '日本の天気', 2, '海風の説明はどれか。', '晴れた日の昼間、海岸付近で海から陸に向かう風', array['晴れた日の夜、海岸付近で海から陸に向かう風', '晴れた日の昼間、海岸付近で陸から海に向かう風', '晴れた日の夜、海岸付近で陸から海に向かう風'], '海から陸へ向かう風が海風である。晴れた日の昼には太陽が照ると、あたたまりやすい陸上の気温が上昇して上昇気流ができて気圧が低くなる。風は気圧が高い方から低い方へ吹くので海から陸に風が吹く。', null),
  ('sci_2_b4_135', '理科', 2, '日本の天気', 2, '日本付近で冬に発達する高気圧はどこにできるか。', 'シベリア', array['オホーツク海', '揚子江付近', '小笠原諸島付近の太平洋'], '陸は海よりあたたまりやすく、冷たくなりやすいので、冬は海より陸のほうが気温が低くなる。そのため陸の高気圧が発達しシベリア付近に冷たい高気圧が発達する。', null),
  ('sci_2_b4_136', '理科', 2, '日本の天気', 2, '日本付近で夏に発達する高気圧はどこにできるか。', '小笠原諸島付近の太平洋', array['オホーツク海', '揚子江付近', 'シベリア'], '夏は冬と逆に陸より海の高気圧のほうが発達するので、日本付近では小笠原諸島付近の太平洋に高気圧が発達する。', null),
  ('sci_2_b4_137', '理科', 2, '前線と天気の変化', 2, '台風は何が発達したもののことか。', '熱帯低気圧', array['温帯低気圧', '移動性高気圧', '小笠原気団'], '赤道付近で発生した熱帯低気圧が発達し、風速17m/sを超えると台風になる。', null),
  ('sci_2_b4_138', '理科', 2, '前線と天気の変化', 2, '前線をともなうことが多いのはどれか。', '温帯低気圧', array['熱帯低気圧', '台風', '移動性高気圧'], '温帯付近では冷たい空気と暖かい空気が両方あるので、温帯低気圧は前線をともなうことが多い。', null),
  ('sci_2_b4_139', '理科', 2, '前線と天気の変化', 2, '移動性高気圧は日本付近でどちらからどちらへ動いていくか。', '西から東', array['北から南', '東から西', '南から北'], '移動性高気圧は偏西風の影響で西から東へ移動する。', null),
  ('sci_2_b4_140', '理科', 2, '前線と天気の変化', 2, '低気圧は日本付近でどちらからどちらへ動いていくか。', '西から東', array['北から南', '東から西', '南から北'], '日本付近での低気圧は偏西風の影響で西から東へ移動する。', null),
  ('sci_2_b4_141', '理科', 2, '前線と天気の変化', 2, '北半球では風は進行方向に対してどちら向きの力を受けるか。', '右', array['左', '前', '後'], '地球の自転によって北半球では進行方向に対して右向きの力を受ける。', null),
  ('sci_2_b4_142', '理科', 2, '前線と天気の変化', 2, '等圧線の細い線は何hPaごとにひくか。', '4hPa', array['2hPa', '10hPa', '20hPa'], '同時刻の気圧の等しいところを結んだ曲線が等圧線である。等圧線は4hPaごとに細い線をひく。', null),
  ('sci_2_b4_143', '理科', 2, '前線と天気の変化', 2, '等圧線の太い線は何hPaごとにひくか。', '20hPa', array['2hPa', '4hPa', '10hPa'], '等圧線は20hPaごとに太線にする。', null),
  ('sci_2_b4_144', '理科', 2, '前線と天気の変化', 1, '等圧線の基準は何hPaか。', '1000hPa', array['1013hPa', '998hPa', '20hPa'], '等圧線の基準は1000hPaである。', null),
  ('sci_2_b4_145', '理科', 2, '前線と天気の変化', 1, '風が強いのはどれか。', '等圧線の間隔が狭い', array['等圧線の間隔が広い', '気圧が高い', '気圧が低い'], '等圧線の間隔が狭いほど強い風が吹く', null),
  ('sci_2_b4_146', '理科', 2, '前線と天気の変化', 2, '寒冷前線でよく見られる雲はどれか。', '積乱雲', array['乱層雲', '高積雲', '高層雲'], '寒冷前線では積雲や積乱雲がよくみられる。', null),
  ('sci_2_b4_147', '理科', 2, '前線と天気の変化', 2, '寒冷前線の特徴はどれか。', '狭い範囲に強い雨が降り、通過後気温が下がる。', array['狭い範囲に強い雨が降り、通過後気温が上昇する。', '広い範囲に弱い雨が降り、通過後気温が上昇する。', '広い範囲に弱い雨が降り、通過後気温が下がる。'], '短い時間(狭い範囲)、強い雨が降り、通過後、北寄りの風が吹き、気温が下がる。', null),
  ('sci_2_b4_148', '理科', 2, '前線と天気の変化', 1, '梅雨前線はどれか。', '停滞前線', array['寒冷前線', '温暖前線', '閉塞前線'], '日本付近にできる停滞前線には梅雨の時期の梅雨前線や、秋にできる秋雨前線がある。', null),
  ('sci_2_b4_149', '理科', 2, '前線と天気の変化', 2, '閉塞前線とは何か。', '寒冷前線が温暖前線に追いついてできる前線。', array['寒気団が暖気団を押し上げる前線。', '暖気団が寒気団の上にはい上がる前線。', '寒気団と暖気団が同じ勢いでぶつかり合う前線。'], '温帯低気圧には寒冷前線と温暖前線ができることが多いが、寒冷前線のほうが速いので温暖前線に追いついてしまう。するとそこが閉塞前線になる。', null),
  ('sci_2_b4_150', '理科', 2, '気象の観測', 3, '1hPaは何Paか。', '100', array['10', '1000', '0.24'], 'h(ヘクト)は100のことなので1hPa=100Paである。', null),
  ('sci_2_b4_151', '理科', 2, '気象の観測', 3, '1気圧はおよそ何hPaか。', '1013', array['100', '1000', '1024'], '海面と同じ高さのところの平均気圧が1気圧で約1013hPaである。', null),
  ('sci_2_b4_152', '理科', 2, '気象の観測', 2, '北半球での高気圧の風の吹き方はどれか。', '中心から右回りに風が吹き出す', array['中心に向かって左回りに風が吹き込む', '中心に向かって右回りに風が吹き込む', '中心から左回りに風が吹き出す'], '高気圧は中心から外へ向かって風が吹き出す。北半球では右回りとなる。', null),
  ('sci_2_b4_153', '理科', 2, '気象の観測', 2, '北半球での低気圧の風の吹き方はどれか。', '中心に向かって左回りに風が吹き込む', array['中心に向かって右回りに風が吹き込む', '中心から左回りに風が吹き出す', '中心から右回りに風が吹き出す'], '低気圧はまわりから中心に向かって風が吹き込む。北半球では左回りとなる。', null),
  ('sci_2_b4_154', '理科', 2, '気象の観測', 1, '晴れの雲量はどれか。', '2〜8', array['0〜1', '9〜10', '0.5'], '雲量0〜1が快晴、雲量9〜10がくもりである。', null),
  ('sci_2_b4_155', '理科', 2, '電流と電圧', 2, '直列回路とは何か。', '電流が枝分かれしない回路', array['電流の向きが一定の回路', '電流がまっすぐに流れる回路', '大きな電流が流れる回路'], '電流の流れる道すじが1本道で枝分かれしない回路が直列回路である。', null),
  ('sci_2_b4_156', '理科', 2, '電流と電圧', 2, '並列回路とは何か。', '電流の流れる道すじが枝分かれする回路', array['電流の向きが周期的に変化する回路', '大きな電流が流れる回路', '小さな電流が流れる回路'], '電流の流れる道すじが枝分かれしている回路が並列回路である。', null),
  ('sci_2_b4_157', '理科', 2, '電流と電圧', 3, '1AをmAに直すといくつか。', '1000mA', array['10mA', '100mA', '10000mA'], '電流の単位はA（アンペア)またはmA(ミリアンペア)をつかう。1A=1000mAである。', null),
  ('sci_2_b4_158', '理科', 2, '電流と電圧', 2, '直列回路で同じ大きさになるのはどれか。', '電流', array['電流と電圧', '電圧', 'どちらでもない。'], '直列回路では電流はどこでも等しい、電圧は各抵抗にかかる電圧の和が電源の電圧に等しくなる。', null),
  ('sci_2_b4_159', '理科', 2, '電流と電圧', 2, '並列回路で同じ大きさになるのはどれか。', '電圧', array['電流と電圧', '電流', 'どちらでもない。'], '並列回路では、各抵抗にかかる電圧が等しい、枝分かれした電流の和が枝分かれする前の電流に等しい。', null),
  ('sci_2_b4_160', '理科', 2, '電流と電圧', 2, '電流の大きさが予想できないとき、電流計のマイナス端子はどこにつなぐか。', '5A', array['50mA', '500mA', '+端子'], '電流の予想ができないときは、いちばん強い電流のはかれる5Aの−端子につなぐ。', null),
  ('sci_2_b4_161', '理科', 2, '電流と電圧', 2, '電圧の大きさが予想できないとき、電圧計のマイナス端子はどこにつなぐか。', '300V', array['15V', '3V', '+端子'], '電圧の予想ができない場合、一番大きい電圧のはかれる300Vの−端子につなぐ', null),
  ('sci_2_b4_162', '理科', 2, '電流と電圧', 2, '電流の流れにくさを表す量を何というか。', '電気抵抗', array['まさつ', '抗力', '電圧'], '電流の流れにくさを表す量が電気抵抗で単位はΩ(オーム)である。', null),
  ('sci_2_b4_163', '理科', 2, '電流と電圧', 1, '次のうち、不導体はどれか。', 'ガラス', array['銅', '炭素', '鉄'], '電気抵抗が小さく、電流を通しやすい金属や炭素などの物質を導体という。 また、電気抵抗が大きく、電流をほとんど通さないガラスやゴムなどの物質を不導体(絶縁体)という。', null),
  ('sci_2_b4_164', '理科', 2, '電流と電圧', 2, '抵抗器や電熱線を流れる電流はそれらを加える電圧に比例する。何と言う法則か。', 'オームの法則', array['キルヒホッフの法則', 'フレミングの法則', 'レンツの法則'], 'オームの法則は「抵抗器や電熱線を流れる電流は、加えた電圧に比例する」である。式では 電圧(V)=電流(A)×電気抵抗(Ω) となる。', null),
  ('sci_2_b4_165', '理科', 2, '電流と電圧', 3, '3Ωの抵抗と2Ωの抵抗を直列につないだ回路の全体抵抗はいくつか。', '5Ω', array['6Ω', '2.5Ω', '1.2Ω'], '抵抗を直列につないだ回路では各抵抗の和が全体抵抗になる。', null),
  ('sci_2_b4_166', '理科', 2, '電流と電圧', 3, '3Ωの抵抗と2Ωの抵抗を並列につないだ回路の全体抵抗はいくつか。', '1.2Ω', array['6Ω', '5Ω', '2.5Ω'], '抵抗を並列につないだ回路では各抵抗の逆数の和が全体抵抗の逆数になる。 1/2+1/3=5/6、6÷5=1.2', null),
  ('sci_2_b4_167', '理科', 2, '電力と熱量', 2, '電流(A)×電圧(V)の式で求められるものはどれか。', '電力', array['発熱量', '抵抗', '電力量'], '1秒間に発生する電気エネルギーの量を電力という。電力は電流(A)×電圧(V)によって求められる。', null),
  ('sci_2_b4_168', '理科', 2, '電力と熱量', 1, '発熱量を求める式はどれか。', '電力×時間', array['電流×電圧', '電圧÷電流', '電力÷時間'], '電熱線は電気エネルギーを熱エネルギーに変換する。発生する熱量(発熱量)は電力と時間に比例する。 発熱量=電力×時間である。', null),
  ('sci_2_b4_169', '理科', 2, '電力と熱量', 2, '単位にJ(ジュール)を用いないものを選べ。', '消費電力', array['発熱量', '電力量', '電気エネルギー'], 'Jはエネルギーの単位で、発熱量や電力量の単位にもJをつかう。消費電力の単位は(ワット)である。', null),
  ('sci_2_b4_170', '理科', 2, '電力と熱量', 3, '1kWは何Wか。', '1000W', array['10W', '100W', '10000W'], 'kは1000のことなので、1kW=1000Wである。', null),
  ('sci_2_b4_171', '理科', 2, '電力と熱量', 2, '水1gを1℃上昇させる熱量はどれか。', '1cal', array['1W', '1J', '1Wh'], '熱量の単位にはJ(ジュール)やcal(カロリー)がある。1gの水を1℃上昇させる熱量が1calで、1cal=約4.2Jである。', null),
  ('sci_2_b4_172', '理科', 2, '電力と熱量', 3, '1kWhは何Jか。', '3600000J', array['1000J', '3600J', '1000000J'], '電力量(J)=電力(W)×時間(s)、電力量(Wh)=電力(W)×時間(h)なので、1kWh=1000×1W×1h=1000×1W×3600s=3600000Jとなる。', null),
  ('sci_2_b4_173', '理科', 2, '静電気と電流', 2, '電子について正しいのはどれか。', '-の電気を帯びた粒子', array['+の電気を帯びた粒子', '電気的に中性の粒子', '原子の中にあり、原子の質量の大部分をしめている。'], '電子は原子の中にあるマイナスの電気を帯びた粒子のことである。質量は非常に小さい。', null),
  ('sci_2_b4_174', '理科', 2, '静電気と電流', 2, '放電について間違っているのはどれか。', '豆電球はこれを利用している。', array['電気が空間を移動すること。', 'たまっていた電気が流れだす現象。', '圧力の低い気体の方が起こりやすい。'], '電気が空間を移動したり、たまっていた電気が流れだす現象を放電という。放電は圧力の低い気体の方が起こりやすく、それを真空放電という。自然現象での放電の例が雷、真空放電を利用した物には蛍光灯などがある。', null),
  ('sci_2_b4_175', '理科', 2, '静電気と電流', 2, '自由電子について間違っているのはどれか。', '電圧をかけると動きが止まる。', array['金属の中にある。', '電圧をかけないとあちこち自由に動いている。', '電流の正体になる。'], '金属では、原子の中の一部の電子が自由に動きまわっている。これを自由電子という。金属に電圧をかけると、自由に動きまわっていた電子が一斉に+の方向に動く。これが電流の正体である。', null),
  ('sci_2_b4_176', '理科', 2, '静電気と電流', 2, 'クルックス管の実験について正しいものはどれか。', '電子の流れのことを陰極線という。', array['+極から電子の流れが出る。', '電子の流れはあらゆる向きに進む', '電子の流れは電気を帯びていない'], 'クルックス管(真空放電管)で、マイナス極(陰極)からでる電子の流れを陰極線という。陰極線は直進する。陰極線は電子の流れなのでマイナスの電気を持っている。', null),
  ('sci_2_b4_177', '理科', 2, '化学変化と分解', 2, '炭酸水素ナトリウムと炭酸ナトリウムで水に溶けやすいのはどちらか。', '炭酸ナトリウム', array['同じくらい溶ける', '炭酸水素ナトリウム', 'どちらも水に溶けない'], '炭酸水素ナトリウムを熱分解した後にできる炭酸ナトリウムは、炭酸水素ナトリウムに比べて水に溶けやすい。', null),
  ('sci_2_b4_178', '理科', 2, '酸化と還元', 2, '銅と水素ではどちらが酸素と結びつきやすいか。', '水素', array['銅', '同じ', '温度によって変わる'], '水素や炭素は非常に酸素と結びつきやすいので、還元剤として使われる。', null),
  ('sci_2_b4_179', '理科', 2, '消化と吸収', 2, '肉食動物で発達している、えものをしとめるための歯はどれか。', '犬歯', array['門歯', '臼歯', '乳歯'], '肉食動物はえものをしとめるための犬歯が発達している。一方草食動物は草を切る門歯やすりつぶす臼歯が発達している。', null),
  ('sci_2_b4_180', '理科', 2, '消化と吸収', 2, 'アミラーゼが分解する栄養素はどれか。', 'デンプン', array['脂肪', 'タンパク質', 'ブドウ糖'], 'アミラーゼは唾液やすい液に含まれる消化酵素でデンプンを分解して糖(麦芽糖)に変える。', null),
  ('sci_2_b4_181', '理科', 2, '消化と吸収', 2, 'ペプシンが分解する栄養素はどれか。', 'タンパク質', array['脂肪', 'デンプン', 'アミノ酸'], 'ペプシンは胃液に含まれる消化酵素でタンパク質を分解する。', null),
  ('sci_2_b4_182', '理科', 2, '消化と吸収', 2, 'タンパク質を分解する消化酵素はどれか。', 'トリプシン', array['アミラーゼ', 'リパーゼ', '胆汁'], 'タンパク質は胃液に含まれるペプシンによって分解され、さらにすい液に含まれるトリプシンなどで分解され、最終的に小腸の壁の酵素によってアミノ酸に分解される。', null),
  ('sci_2_b4_183', '理科', 2, '圧力', 2, '力の大きさが同じで面積が小さいと圧力はどうなるか。', '大きくなる', array['同じ', '小さくなる', '力の大きさだけで決まる'], '力の大きさが同じなら面積の小さいほうが圧力は大きくなる。', null),
  ('sci_2_b4_184', '理科', 2, '日本の天気', 2, '陸と海ではどちらがあたたまりやすいか。', '陸', array['海', '同じ', '季節によって入れかわる'], '常温の物質では水が最もあたたまりにくく、さめにくい。そのため海と陸では陸のほうがあたたまりやすい。', null),
  ('sci_2_b4_185', '理科', 2, '気象の観測', 2, '高気圧の中心付近ではどのような空気の動きがあるか。', '下降気流', array['上昇気流', '空気の動きはない', '水平方向に吹きこむ流れ'], '高気圧はまわりより気圧の高いところで、中心付近では下降気流がある。', null),
  ('sci_2_b4_186', '理科', 2, '前線と天気の変化', 2, '風はどこからどこへ向かって吹くか。', '高気圧から低気圧', array['低気圧から高気圧', 'きまっていない', '気温の高いところから低いところ'], '風は気圧の高い方から低い方へ向かって吹く。', null),
  ('sci_2_b4_187', '理科', 2, '静電気と電流', 2, '電気の引きあう力がはたらくのはどの場合か。', '+の電気と-の電気', array['+の電気と+の電気', '-の電気と-の電気', '電気を帯びていないもの同士'], '電気には+と-の種類があり、同じ種類の電気どうしはしりぞけあい、異なる種類の電気は引き合う力がはたらく。', null),
  ('sci_2_b4_188', '理科', 2, '静電気と電流', 2, '異なる種類の物体をこすり合わせるとどうなるか。', '-の電気を帯びた粒子が一方から他方へ移る', array['+の電気を帯びた粒子が一方から他方へ移る', '+の電気と-の電気がそれぞれ他方に移る', '+の電気と-の電気が新しくつくられる'], '異なる種類の物質をたがいにまさつすると、一方から他方へマイナスの電気(電子)が移動する。電子を失った方はプラスに帯電し、電子を受け取った方はマイナスに帯電する。これが静電気である。', null),
  ('sci_3_b4_001', '理科', 3, '細胞分裂', 2, '細胞分裂の際に核の中に現れるひも状のものを何というか。', '染色体', array['ミトコンドリア', '細胞紐', '核膜'], '染色体とは遺伝子の集合体で、細胞分裂のときに核に現れる。体細胞分裂のときに染色体もコピーされて2つに分かれるので染色体数は変化しない。', null),
  ('sci_3_b4_002', '理科', 3, '細胞分裂', 2, '植物で細胞分裂のさかんなところはどこか。', '根の先端付近', array['表皮', '茎の中心付近', '道管'], '植物では根や茎の先端付近で細胞分裂がさかんである。最も細胞分裂のさかんなところを成長点という。', null),
  ('sci_3_b4_003', '理科', 3, '細胞分裂', 2, '根の先端を保護している組織を何というか。', '根冠', array['根毛', 'ひげ根', '主根'], '根の先端で成長点を保護する組織を根冠という。', null),
  ('sci_3_b4_004', '理科', 3, '細胞分裂', 2, '生物は細胞分裂して、さらに細胞の大きさが大きくなることで（　　）する。', '成長', array['衰退', '生殖', '発生'], '生物は、細胞分裂で細胞の数が増えることと、1つ1つの細胞の大きさが大きくなること、この2つによって成長する。', null),
  ('sci_3_b4_005', '理科', 3, '細胞分裂', 2, '生物の細胞のうち生殖細胞以外のふつうの細胞のことを何というか。', '体細胞', array['普通細胞', '精細胞', '卵細胞'], '生殖に関わる特別な細胞が生殖細胞で、それ以外のふつうの細胞を体細胞という。', null),
  ('sci_3_b4_006', '理科', 3, '細胞分裂', 2, '酢酸オルセイン溶液は何を染める染色液か。', '染色体', array['細胞壁', '葉緑体', '細胞膜'], '染色体は酢酸オルセイン溶液や酢酸カーミン溶液、酢酸ダーリア溶液などによく染まり、赤紫色になる。', null),
  ('sci_3_b4_007', '理科', 3, '生物のふえ方', 2, '無性生殖とは関係無いものはどれか。', '花粉', array['胞子', '分裂', 'むかご'], '雌雄に関係なく、親の体の一部が分かれてそれがそのまま子になることを無性生殖という。単細胞生物の分裂、栄養生殖(むかご、いも、球根、さし木)、胞子などが無性生殖である。', null),
  ('sci_3_b4_008', '理科', 3, '生物のふえ方', 2, '分裂によってふえる生物はどれか。', 'ミカヅキモ', array['ジャガイモ', 'カエル', 'スギゴケ'], 'アメーバやミカヅキモなどの単細胞生物は体細胞分裂で体が2つに分かれることでなかまをふやす。', null),
  ('sci_3_b4_009', '理科', 3, '生物のふえ方', 2, '栄養生殖ではないものはどれか。', '種子', array['むかご', '球根', 'さし木'], 'いも、むかご、さし木、球根など、植物の体の一部から芽が出てそのまま育ち、新個体になることを栄養生殖といい、無性生殖のひとつである。種子は有性生殖によってできる。', null),
  ('sci_3_b4_010', '理科', 3, '生物のふえ方', 2, '雄と雌が関わって子孫をつくる生殖を何というか。', '有性生殖', array['栄養生殖', '分裂', '無性生殖'], '多くの動物、植物で行われている、雄と雌がかかわって子孫を作る生殖を有性生殖という。', null),
  ('sci_3_b4_011', '理科', 3, '生物のふえ方', 2, '生殖細胞ではないものはどれか。', '胚', array['精子', '卵', '精細胞'], '有性生殖を行なうための特別な細胞を生殖細胞という。雄の精子、精細胞や雌の卵、卵細胞が生殖細胞である。', null),
  ('sci_3_b4_012', '理科', 3, '生物のふえ方', 2, '染色体数が体細胞の半分なのはどれか。', '卵細胞', array['受精卵', '胚', '成長点の細胞'], '生殖細胞は染色体数が体細胞の半分になる。', null),
  ('sci_3_b4_013', '理科', 3, '生物のふえ方', 2, '精細胞(精子)の核と卵細胞(卵)の核が合体することを何というか。', '受精', array['分裂', '遺伝', '受粉'], '精細胞(精子)の核と卵細胞(卵)の核が合体し受精卵ができる。これを受精という。', null),
  ('sci_3_b4_014', '理科', 3, '生物のふえ方', 2, '受精卵が細胞分裂してから成体または幼生になる前の段階のものを何というか。', '胚', array['卵', '個体', '生殖細胞'], '受精によってできた受精卵は1つの細胞だが、これが細胞分裂をして胚となる。胚はさらに細胞分裂して生物の個体となっていく。', null),
  ('sci_3_b4_015', '理科', 3, '生物のふえ方', 2, '受精してから成体になるまでの過程を何というか。', '発生', array['成長', '受精', '遺伝'], '受精卵が体細胞分裂をして胚になり、それを経て成体になるまでの過程のことを発生という。', null),
  ('sci_3_b4_016', '理科', 3, '生物のふえ方', 2, '生殖細胞を作るための特別な細胞分裂を何というか。', '減数分裂', array['体細胞分裂', '特別分裂', '生殖分裂'], '生殖細胞をつくるための細胞分裂を減数分裂という。減数分裂では体細胞分裂と違い、分裂後の染色体数が半分になる。', null),
  ('sci_3_b4_017', '理科', 3, '生物のふえ方', 3, 'エンドウの体細胞の染色体数は14である。エンドウの受精卵の染色体数はいくつか。', '14', array['7', '28', '10'], '生殖細胞以外の体細胞の染色体数はすべて同じである。受精卵は生殖細胞ではないので体細胞と同じ染色体数になる。', null),
  ('sci_3_b4_018', '理科', 3, '生物のふえ方', 3, 'エンドウの体細胞の染色体数は14である。エンドウの卵細胞の染色体数はいくつか。', '7', array['14', '28', '10'], '卵細胞や精細胞など生殖細胞の染色体数は体細胞の半分である。', null),
  ('sci_3_b4_019', '理科', 3, '生物のふえ方', 2, '受粉後、花粉管の中を移動していくものは何か。', '精細胞', array['卵細胞', '花粉', '胚珠'], 'めしべの柱頭についた花粉は花粉管をのばす。その花粉管の中を精細胞が移動していく。', null),
  ('sci_3_b4_020', '理科', 3, '遺伝の規則性', 2, '核の中に一対で存在し、遺伝する形質のもととなるものを何というか。', '遺伝子', array['DNA', '胚', 'ミトコンドリア'], '遺伝する形質のもととなるものが遺伝子であり、核の染色体にある。遺伝子は一対となっていて両親からそれぞれ受け継ぐ。遺伝子の本体はDNA(デオキシリボ核酸)という物質である。', null),
  ('sci_3_b4_021', '理科', 3, '遺伝の規則性', 2, '有性生殖では子の遺伝子は（　　）になる。', '両親の遺伝子を半分ずつ受け継ぐ。', array['親と全く同じ遺伝子', '優性の遺伝子だけ受け継ぐ。', '潜性の遺伝子だけ受け継ぐ。'], '有性生殖では両親の遺伝子をそれぞれ半分ずつ受け継ぐことになる。', null),
  ('sci_3_b4_022', '理科', 3, '遺伝の規則性', 2, '無性生殖について正しいものはどれか。', '遺伝子が親と子で全く同じ、形質も親と子で全く同じ。', array['遺伝子は親と子で全く同じだが形質は異なる。', '親と子で遺伝子は異なるが、形質が全く同じ。', '親と子で遺伝子も形質も異なる。'], '無性生殖では親の体の一部がそのまま子になるので、子は親と全く同じ遺伝子で全く同じ形質が現れる。', null),
  ('sci_3_b4_023', '理科', 3, '遺伝の規則性', 2, '遺伝の規則性を発見した19世紀オーストリアの学者は誰か。', 'メンデル', array['アンペール', 'フック', 'アボガドロ'], 'メンデルは19世紀オーストリアの生物学者でエンドウの実験をおこなって遺伝の規則性を発見した。', null),
  ('sci_3_b4_024', '理科', 3, '遺伝の規則性', 2, '対立形質とはなにか。', '同時に現れない2つの形質', array['正反対の形質', '必ず同時に現れる2つの形質', '子に現れず孫に現れる形質'], '同時に現れない2つの形質を対立形質という。', null),
  ('sci_3_b4_025', '理科', 3, '遺伝の規則性', 2, '対立形質である純系の赤い花と純系の白い花をかけあわせたら、子はすべて赤い花になった。子を自家受精して得られる孫の赤い花と白い花の比はどうなるか。', '白が赤の3分の1', array['全て赤い花', '全て白い花', '赤と白が半分ずつ'], '対立形質の純系どうしを掛けあわせてできる子の遺伝子はAaとなり、子を自家受精させると孫の遺伝子はAA、Aa、Aa、aaとなる。AA、Aa、Aaは顕性形質が現れ、aaは潜性形質が現れるので、比は3:1である。', null),
  ('sci_3_b4_026', '理科', 3, '太陽系と銀河系', 2, '恒星とは何か。', '自ら光を出す星', array['動かない星', '明るさが変化しない星', '光を反射する星'], '太陽や星座の星など自ら光や熱を出して輝く天体を恒星という。', null),
  ('sci_3_b4_027', '理科', 3, '太陽系と銀河系', 2, '肉眼で見える最も暗い星は（　　）等星である。', '6', array['7', '5', '4'], '星の明るさは等級であらわし、1等級の星を1等星という。じゅうぶん暗い空で肉眼で見える最も暗い星が6等星である。', null),
  ('sci_3_b4_028', '理科', 3, '太陽系と銀河系', 2, '星の等級が1等級小さくなるごとに明るさが約（　　）になる。', '2.5倍', array['100倍', '6倍', '25倍'], '肉眼で見える最も暗い星が6等星で、1等星はその100倍の明るさである。1等級ちいさくなると約2.5倍明るくなる。', null),
  ('sci_3_b4_029', '理科', 3, '太陽系と銀河系', 2, '太陽以外で最も明るい恒星は何か。', 'おおいぬ座のシリウス', array['こと座のベガ', 'オリオン座のベテルギウス', 'こいぬ座のプロキオン'], '太陽以外の恒星で最も明るいのはおおいぬ座のシリウスで-1.5等級である。', null),
  ('sci_3_b4_030', '理科', 3, '太陽系と銀河系', 2, '宇宙に無数にある、恒星が数億から数千億集まった集団を何というか。', '銀河', array['星団', '星雲', '銀河系'], '宇宙には星が均一に広がるのではなく、恒星はまとまった集団を作って存在している。その、恒星が数億から数千億あつまった集団のことを銀河という。', null),
  ('sci_3_b4_031', '理科', 3, '太陽系と銀河系', 2, '太陽系には地球を含む（　　）個の惑星がある。', '8個', array['1000億個', '9個', '7個'], '太陽とそのまわりを公転する天体をまとめて太陽系という。そのうち水星、金星、地球、火星、木星、土星、天王星、海王星の8つの天体を惑星という。', null),
  ('sci_3_b4_032', '理科', 3, '太陽系と銀河系', 1, '光年とは何か。', '距離を表す単位', array['時間を表す単位', '光の強さを表す単位', '光の速さを表す単位'], '天体の間の距離は非常に大きいのでkmなどでは表さない。光年は天体間の距離を表す単位の一つで光が1年間に進む距離を1光年としている。', null),
  ('sci_3_b4_033', '理科', 3, '太陽系と銀河系', 2, '天文単位とは（　　）を1天文単位として、天体間の距離を表す単位である。', '地球から太陽までの距離', array['光が1年間に進む距離', '地球から月までの距離', '光が1秒間に進む距離'], '天体の間の距離は非常に大きいのでkmなどでは表さない。天文単位は天体間の距離を表す単位の一つで、地球から太陽までの距離を1天文単位としている。', null),
  ('sci_3_b4_034', '理科', 3, '太陽系と銀河系', 2, '地球が所属する銀河を銀河系といい、渦を巻いた（　　）の形をしている。', '円盤状', array['円錐形', '円筒形', 'ドーナツ状'], '地球が所属する銀河を銀河系という。銀河系は直径が約10万光年で、渦を巻いた円盤状をしている。', null),
  ('sci_3_b4_035', '理科', 3, '太陽系と銀河系', 2, '銀河系を地球から見たものを何というか。', '天の川', array['アンドロメダ銀河', 'すばる', 'ブラックホール'], '地球は銀河系の内部にあるので、地球から銀河系をみると恒星が帯状の川のようにみえる。これを天の川という。', null),
  ('sci_3_b4_036', '理科', 3, '太陽系と銀河系', 2, '太陽系の惑星について間違っていることはどれか。', 'どの惑星も表面が岩石でできている。', array['ほぼ同じ平面上を公転している', '全ての惑星が同じ向きに公転している', '太陽から遠いほど公転周期が長くなる'], '惑星には表面が岩石でできているものと、ガスなど軽い物質で出来ているものがある。', null),
  ('sci_3_b4_037', '理科', 3, '太陽系と銀河系', 1, '地球型惑星はどれか。', '水星', array['天王星', '土星', '海王星'], '水星、金星、地球、火星を地球型惑星といい、それ以外の木星、土星、天王星、海王星が木星型惑星である。', null),
  ('sci_3_b4_038', '理科', 3, '太陽系と銀河系', 2, '木星型惑星の特徴はどれか。', '環がある', array['地球より内側を公転している', '密度が大きい', '質量が小さい'], '木星型惑星は軽い物質でできており密度が小さく、環がある。地球型惑星は主に岩石と金属からできており密度が大きい。', null),
  ('sci_3_b4_039', '理科', 3, '太陽系と銀河系', 2, '最も太陽の近くを公転している惑星はどれか。', '水星', array['金星', '火星', '土星'], '最も太陽の近くを公転しているのは水星である。', null),
  ('sci_3_b4_040', '理科', 3, '太陽系と銀河系', 1, '最も大きい惑星はどれか。', '木星', array['金星', '火星', '土星'], '最も大きい惑星は木星である。', null),
  ('sci_3_b4_041', '理科', 3, '太陽系と銀河系', 2, '硫酸の雲におおわれていて、表面の平均気温が400℃以上ある惑星はどれか。', '金星', array['火星', '木星', '土星'], '金星は地球のすぐ内側を公転する惑星で、大きさも地球と似ているが、大気の主な成分が二酸化炭素で、厚い硫酸の雲におおわれ平均気温が約400℃になる。', null),
  ('sci_3_b4_042', '理科', 3, '太陽系と銀河系', 2, '惑星のまわりを回る天体を何というか。', '衛星', array['小惑星', 'すい星', '惑星'], '惑星のまわりを回る天体が衛星である。地球の衛星は月、火星の衛星はフォボスとダイモス、木星にはガニメデやエウロパを含む多数の衛星が見つかっている。', null),
  ('sci_3_b4_043', '理科', 3, '太陽系と銀河系', 2, '日本の「はやぶさ」が探索した「イトカワ」など、火星と木星の軌道のあいだにたくさんある天体は何か。', '小惑星', array['すい星', '惑星', '衛星'], '小惑星は主に火星と木星の軌道の間にあるが、形や軌道はさまざまである。', null),
  ('sci_3_b4_044', '理科', 3, '太陽系と銀河系', 2, '海王星より外側にある、冥王星のような天体を何というか。', '太陽系外縁天体', array['外惑星', 'すい星', '小惑星'], '冥王星は以前は惑星とされていたが、海王星より外側の観測・研究が進んだ結果、同様の天体が多数あることがわかり、これらを太陽系外縁天体と分類することになった。', null),
  ('sci_3_b4_045', '理科', 3, '太陽系と銀河系', 2, '太陽系のまわりを細長いだ円軌道で回る、おもに氷やちりでできている小天体は何か。', 'すい星', array['小惑星', '惑星', '衛星'], '太陽系のまわりを細長いだ円軌道で回る小天体がすい星である。おもに氷やちりでできており、太陽に近づくと温度が上がってガスやちりを放出して太陽と反対側に尾をつくることがある。', null),
  ('sci_3_b4_046', '理科', 3, '地球の運動と天体の動き', 2, '日本で、日の出、日の入りの方角が最も南寄りになるのはいつか。', '冬至', array['春分', '秋分', '夏至'], '日の出日の入りの方角は春分、秋分のとき真東と真西にで、冬になると南に寄り、冬至の時に最も南寄りになる。', null),
  ('sci_3_b4_047', '理科', 3, '地球の運動と天体の動き', 2, '日本で、昼の長さと夜の長さがほぼ同じになるのはいつか。', '春分と秋分', array['夏至', '冬至', '一年中'], '昼の長さは季節によって変化し、夏が長く冬が短い。春分と秋分のときは昼と夜がほぼ同じである。', null),
  ('sci_3_b4_048', '理科', 3, '地球の運動と天体の動き', 2, '季節によって日の出日の入りの方角や昼の長さが変わるのはなぜか。', '地軸が公転面に対して垂直ではなく、傾いたまま地球が公転しているから。', array['地球が太陽の回りを公転しているから。', '地球の公転軌道が円ではなくだ円だから。', '太陽の活動が変化するから。'], '地球は公転面に対して地軸が垂直から23.4°ずれたまま公転している。このため昼の長さや、日の出日の入りの位置、太陽の南中高度が変化する。', null),
  ('sci_3_b4_049', '理科', 3, '地球の運動と天体の動き', 3, '北緯36°の秋分の日の太陽の南中高度は何度か。', '54°', array['36°', '23.4°', '77.4°'], '春分、秋分の太陽の南中高度は90°-緯度で出すことができる。', null),
  ('sci_3_b4_050', '理科', 3, '地球の運動と天体の動き', 3, '北緯35°の冬至の日の太陽の南中高度は何度か。', '31.6°', array['35°', '55°', '23.4°'], '冬至の日の南中高度は90°-緯度-23.4°となる。夏至の日は90°-緯度+23.4°である。', null),
  ('sci_3_b4_051', '理科', 3, '地球の運動と天体の動き', 2, '夏、気温が高い理由は、昼の長さが長いことともうひとつ理由がある。それはどれか。', '太陽からの光が垂直に近くなって受け取るエネルギーが増える。', array['太陽までの距離が近いので太陽から受け取るエネルギーが増える。', '空気中の水蒸気が少ないので太陽からとどく光の量が増える。', '太陽の活動が活発になるので太陽からとどくエネルギーが増える。'], '地球は公転面に対して地軸が垂直から23.4°ずれたまま公転している。このため夏は南中高度が高く、地面に垂直に近い角度で太陽光があたる。これによってより多くのエネルギーを受け取ることになる。', null),
  ('sci_3_b4_052', '理科', 3, '地球の運動と天体の動き', 2, '地球が太陽の回りを1年かかって1周する運動を（　　）という。', '公転', array['年周運動', '自転', '等速円運動'], '天体がほかの天体のまわりを回る運動を公転という。地球は惑星なので太陽のまわりを公転している。地球の公転周期は1年である。', null),
  ('sci_3_b4_053', '理科', 3, '地球の運動と天体の動き', 2, '（　　）を結ぶ軸を地軸という。', '北極と南極', array['中心と天頂', '北極星と太陽', '東と西'], '地球の北極と南極を結ぶ軸を地軸という。', null),
  ('sci_3_b4_054', '理科', 3, '地球の運動と天体の動き', 2, '地球が地軸を中心に（　　）、回転する運動を自転という。', '1日で1周', array['1年で1周', '1日で15°', '1日1°'], '物体が自身の内部を通る軸のまわりを回転することを自転という。地球の自転軸が地軸である。地球の自転周期は1日である。', null),
  ('sci_3_b4_055', '理科', 3, '地球の運動と天体の動き', 2, '自転と公転の向きは北極側から見て（　　）である。', '両方とも反時計回り', array['両方とも時計回り', '自転が時計回りで公転が反時計回り', '自転が反時計回りで、公転が時計回り'], '地球の公転と自転の向きは同じで、北極側から見ると反時計回りである。', null),
  ('sci_3_b4_056', '理科', 3, '地球の運動と天体の動き', 2, '地球の地軸と公転面の角度について正しいのはどれか。', '常に垂直から23.4°傾いたまま公転している。', array['地軸と公転面は垂直のまま公転している。', '春分と秋分は垂直で、夏至は23.4°、冬至は逆に23.4°傾く。', '地軸と公転面が同一平面上にある。'], '地球は地軸を公転面に対して垂直から23.4°傾けて公転している。この角度は1年中同じである。', null),
  ('sci_3_b4_057', '理科', 3, '月の運動と見え方', 2, '月について間違っているのはどれか。', '自転せず、地球から常に同じ面が見える', array['地球に最も近い天体である', '地球のまわりを公転する衛星である', '周期的に満ち欠けする'], '月は地球の回りを回る衛星で、地球から最も近い天体である。月は公転と自転の周期が同じなので常に地球から同じ面がみえる。太陽の光を反射して輝いており地球から見ると満ち欠けをする', null),
  ('sci_3_b4_058', '理科', 3, '月の運動と見え方', 2, '満月から、次の満月までの日数はどれか。', '約29.5日', array['約27日', '約31日', '約7日'], '月の自転周期は約27日だが、満月から満月までの満ち欠けの周期は約29.5日である。月が同じ時刻に見える位置は1日約12°ずつ西から東へ変化する。', null),
  ('sci_3_b4_059', '理科', 3, '月の運動と見え方', 3, '月が満ち欠けするのはなぜか。', '月は太陽の光を反射して常に半分が輝いているが、地球の回りを公転しているため地球から見た、光っている部分の見え方が変わるから。', array['月は太陽の光を反射して常に半分が輝いているが、月が自転しているため地球から見た、光っている部分の見え方が変わるから。', '月は太陽の光を反射して常に半分が輝いているが、地球が自転しているため地球から見た、光っている部分の見え方が変わるから。', '月は太陽の光を反射して常に半分が輝いているが、地球が太陽の回りを公転しているため地球から見た、光っている部分の見え方が変わるから。'], '月は太陽の光を反射して常に半分が輝いているが、地球のまわりを公転することで地球から見える輝いた部分の割合が変わるため、満ち欠けして見える。', null),
  ('sci_3_b4_060', '理科', 3, '月の運動と見え方', 2, '満月はどれか。', '朝6時頃西の地平線付近に見える', array['真夜中12時頃、東の地平線付近に見える', '夜9時頃、西の空に見える', '午後3時頃、南中する'], '満月は夕方6時ころ東の地平線からのぼり、真夜中南中し、明け方6時ころ西の地平線に沈む', null),
  ('sci_3_b4_061', '理科', 3, '月の運動と見え方', 2, '午前6時に真南に見える月はどれか。', '下弦の月', array['上弦の月', '三日月', '新月'], '下弦の月は観測者から見て左半分が輝く半月で、午前6時頃に南中する。上弦の月は夕方に南中し、新月は光る部分が見えない。', null),
  ('sci_3_b4_062', '理科', 3, '月の運動と見え方', 2, '日食はどれか。', '太陽、月、地球の順に一直線に並び、太陽が月にかくれる。', array['太陽、月、地球の順に一直線に並び、太陽が地球の影にはいる。', '太陽、地球、月の順に一直線に並び、太陽が月にかくれる。', '太陽、地球、月の順に一直線に並び、太陽が地球の影にはいる。'], '太陽、月、地球の順に一直線に並んで、地球の表面に月の影ができる。この影に入った地域では太陽が月にさえぎられて見えなくなる。これが日食である。', null),
  ('sci_3_b4_063', '理科', 3, '月の運動と見え方', 2, '月食はどれか。', '太陽、地球、月の順に一直線に並び、月が地球の影にはいる。', array['太陽、月、地球の順に一直線に並び、月が地球の影にはいる。', '太陽、月、地球の順に一直線に並び、月が太陽にかくれる。', '太陽、地球、月の順に一直線に並び、月が太陽にかくれる。'], '太陽、地球、月の順に一直線に並んで、太陽の光が地球によってさえぎられて月に当たらなくなるのが月食である。', null),
  ('sci_3_b4_064', '理科', 3, '月の運動と見え方', 2, '皆既食とは何か。', '天体が完全にかくされること', array['天体がかくされるような不思議な現象のこと', '様々な天体がかくされること', '天体が急に見えなくなること'], '天体が完全にかくされることを皆既食といい、皆既日食、皆既月食などがある。また、部分的にかくされるのは部分食である。', null),
  ('sci_3_b4_065', '理科', 3, '月の運動と見え方', 2, '皆既日食のときに見られるのはどれか。', 'コロナ', array['黒点', '月の裏側', '磁気嵐'], 'コロナは太陽をとりまく高温(100万℃以上)のガスの層で皆既日食で太陽の光球がかくれると観測できる。', null),
  ('sci_3_b4_066', '理科', 3, '月の運動と見え方', 2, '地球から見た、太陽と月の見かけの大きさはどう違うか。', 'ほぼ同じ', array['太陽が月の約400倍', '太陽が月の約109倍', '月のほうが大きい'], '太陽の半径は月の半径の約400倍で、地球からのそれぞれへの距離も約400倍なので、地球から見た見かけの大きさがほぼ同じになる。', null),
  ('sci_3_b4_067', '理科', 3, '月の運動と見え方', 1, '月食が起こるのはいつか。', '満月のとき', array['新月のとき', '半月のとき', '決まっていない'], '月食は満月の時に起きるが、満月の時にいつも起きるわけではない。', null),
  ('sci_3_b4_068', '理科', 3, '月の運動と見え方', 1, '日食が起こるのはいつか。', '新月のとき', array['満月のとき', '半月のとき', '決まっていない'], '日食が起きるのは新月のときだが、新月の時にいつも日食が起きるわけではない。', null),
  ('sci_3_b4_069', '理科', 3, '太陽', 2, '太陽は主に（　　）できている。', '水素とヘリウム', array['窒素と酸素', '岩石と金属', 'マグマ'], '太陽は水素(約92%)とヘリウム(約8%)からできたガスのかたまりである。', null),
  ('sci_3_b4_070', '理科', 3, '太陽', 2, '太陽表面の黒点とは何か。', 'まわりより温度が低く暗く見えるところ', array['ブラックホール', 'まわりより温度が高くて焦げたところ', '太陽表面にできたくぼみ'], '太陽表面にある黒点はまわりより温度が低いため暗く見える。', null),
  ('sci_3_b4_071', '理科', 3, '太陽', 2, '黒点が太陽表面で（　　）から太陽が自転していることがわかる。', '位置を変えていくこと', array['数が変化すること', '形が変化すること', '活発に活動すること'], '太陽表面の黒点を観察すると、位置が少しずつ移動し約27〜30日で一周している。このことから太陽が自転していることがわかる。ちなみに、太陽が球形であることは黒点の形の変化からわかる。', null),
  ('sci_3_b4_072', '理科', 3, '太陽', 1, '太陽の表面温度は何度か。', '約6000℃', array['約600℃', '約1600万℃', '約100万℃'], '太陽の表面温度は約6000℃である。ちなみに黒点は約4000℃、中心は約1600万℃である。', null),
  ('sci_3_b4_073', '理科', 3, '太陽', 1, '太陽の直径は地球の何倍か。', '約109倍', array['約0.95倍', '約11.2倍', '約33万倍'], '太陽の直径は約140万kmで地球の約109倍である。', null),
  ('sci_3_b4_074', '理科', 3, '酸・アルカリ', 2, 'アルカリ性の水溶液にBTB溶液を入れた場合何色になるか。', '青色', array['緑色', '黄色', '赤色'], 'BTB溶液は中性で緑色、アルカリ性で青色、酸性で黄色になる。', null),
  ('sci_3_b4_075', '理科', 3, '酸・アルカリ', 2, 'アルカリ性の水溶液はどれか。', '石灰水', array['硫酸銅水溶液', 'レモン汁', '砂糖水'], 'アルカリ性の水溶液は石灰水、アンモニア水、水酸化ナトリウム水溶液、石け水などである。硫酸銅水溶液は弱酸性、レモン水は酸性、砂糖水は中性である。', null),
  ('sci_3_b4_076', '理科', 3, '酸・アルカリ', 2, '酸性の水溶液はどれか。', '炭酸水', array['炭酸水素ナトリウム水溶液', 'アンモニア水', '食塩水'], '酸性の水溶液は炭酸水、塩酸、硫酸、硝酸、食酢などである。炭酸水素ナトリウム水溶液とアンモニア水はアルカリ性、食塩水は中性である。', null),
  ('sci_3_b4_077', '理科', 3, '酸・アルカリ', 2, '中性の水溶液のpHはいくつか。', '7', array['0', '5', '10'], 'pHは酸性、アルカリ性の強さを表す0〜14の数字であり、7のとき中性である。', null),
  ('sci_3_b4_078', '理科', 3, '酸・アルカリ', 2, '中性の水溶液を選べ。', '硝酸カリウム水溶液', array['炭酸ナトリウム水溶液', '水酸化バリウム水溶液', '炭酸水'], '中性の水溶液は食塩水、砂糖水、硝酸カリウム水溶液などがある。', null),
  ('sci_3_b4_079', '理科', 3, '酸・アルカリ', 2, '酸性の水溶液に共通して含まれているイオンは何か。', 'H⁺', array['Cl⁻', 'OH⁻', 'K⁺'], '電離したときにH⁺ を生じる物質を酸という。つまりH⁺ が酸性のもとになっている。', null),
  ('sci_3_b4_080', '理科', 3, '酸・アルカリ', 2, 'アルカリ性の水溶液に共通して含まれているイオンは何か。', 'OH⁻', array['Cl⁻', 'H⁺', 'K⁺'], '電離したときにOH⁻ を生じる物質をアルカリという。つまりOH⁻ がアルカリ性のもとになっている。', null),
  ('sci_3_b4_081', '理科', 3, '酸・アルカリ', 2, '酸性の水溶液にマグネシウムを入れたときに発生する気体は何か。', '水素', array['酸素', '二酸化炭素', '塩素'], '酸性の水溶液にマグネシウムをいれるとマグネシウムがMg²⁺ となり放出された電子を水溶液中のH⁺ が受け取って水素原子になりそれが2個くっついて水素分子となって発生する。マグネシウム以外にも亜鉛や鉄などの金属で同じ反応が起こる。', null),
  ('sci_3_b4_082', '理科', 3, '中和と塩', 2, 'はじめにBTB溶液を加えてあったときの色の変化はどれか。', '黄色→緑色→青色', array['黄色→青色→緑色', '緑色→黄色→青色', '青色→緑色→黄色'], '塩酸は酸性なので黄色。水酸化ナトリウム水溶液を加えると徐々に酸性が弱まって中性になり緑色。さらに水酸化ナトリウム水溶液を加えるとアルカリ性になり青色。', null),
  ('sci_3_b4_083', '理科', 3, '中和と塩', 2, 'はじめにマグネシウムリボンを入れてあったときの水素の出方はどれか。', 'さかんに出ていたものがよわくなりやがて止まる', array['はじめから終わりまでずっとさかんに出続ける', 'はじめは出ないがだんだんたくさん出るようになる', 'はじめは出ているが弱くなり途中でとまり、再び出るようになる'], 'マグネシウムは酸性の水溶液と反応して水素を出すので、最初はさかんに水素がでるが中性になった時点ででなくなり、アルカリ性が強くなっても反応しない。', null),
  ('sci_3_b4_084', '理科', 3, '中和と塩', 2, '数が最初から最後まで変化しないイオンはどれか。', 'Cl⁻', array['H⁺', 'Na⁺', 'OH⁻'], 'Cl⁻ は塩酸が電離して発生するので数は変化しない。', null),
  ('sci_3_b4_085', '理科', 3, '中和と塩', 2, '最初は0で加えただけ増えていくイオンはどれか。', 'Na⁺', array['H⁺', 'OH⁻', 'Cl⁻'], 'Na⁺ は水酸化ナトリウムが電離して発生するので、水酸化ナトリウムを加えたぶんだけ増えていく。', null),
  ('sci_3_b4_086', '理科', 3, '中和と塩', 2, '数が少しずつ減り、中性になると0になるイオンはどれか。', 'H⁺', array['Na⁺', 'OH⁻', 'Cl⁻'], '塩酸が電離して発生するH⁺ は加えられたOH⁻ と反応して水になるので徐々に減ってやがて0になる。', null),
  ('sci_3_b4_087', '理科', 3, '中和と塩', 2, '最初から中性まで0で、そのあと加えただけ増えるイオンはどれか。', 'OH⁻', array['H⁺', 'Na⁺', 'Cl⁻'], 'H⁺ が存在するところにOH⁻ をくわえても反応して水になってしまうので数は増えない。中性になってH⁺ がなくなってからは加えたぶんだけ増えていく', null),
  ('sci_3_b4_088', '理科', 3, '中和と塩', 2, '硫酸と水酸化バリウムの中和によってできる塩はどれか。', 'BaSO₄', array['H₂SO₂', 'BaCl₂', 'NaCl'], '硫酸と水酸化バリウムの化学反応式H₂SO₄+Ba(OH)₂→H₂O+BaSO₄ このとき水以外にできているのが塩である。', null),
  ('sci_3_b4_089', '理科', 3, '中和と塩', 2, '塩酸A12cm³と水酸化ナトリウム水溶液B10cm³をまぜると中性になった。塩酸A9cm³を中性にするの水酸化ナトリウム水溶液Bはどれか。', '7.5cm³', array['6cm³', '9cm³', '10.8cm³'], '12:10=9:xより12x=90これを計算してx=7.5', null),
  ('sci_3_b4_090', '理科', 3, '中和と塩', 2, '塩酸P10cm³と水酸化ナトリウム水溶液X8cm³をまぜると中性になった。含まれるイオンの数が最も多いのはどれか。', '水酸化ナトリウム水溶液X20cm³', array['塩酸P20cm³', 'Pの2倍の濃度の塩酸Q10cm³', 'Xの2倍の濃度の水酸化ナトリウムY8cm³'], 'P10cm³とX8cm³は中性になるので、含まれるイオンの数は等しい。X20cm³は濃度が同じで体積が2.5倍なのでイオンの数も2.5倍となり最も多い。残りはいずれも体積か濃度が2倍で、イオンの数は2倍にとどまる。', null),
  ('sci_3_b4_091', '理科', 3, '電池', 2, '電池ができる組み合わせはどれか。', '食塩水、銅板、鉄板', array['うすい塩酸、銅板、銅板', 'エタノール、銅板、亜鉛板', '蒸留水、マグネシウム板、鉄板'], '電池(化学電池)は2種類の金属と電解質水溶液で作ることができる。', null),
  ('sci_3_b4_092', '理科', 3, '電池', 2, 'うすい硫酸に亜鉛板と銅板で作った電池で亜鉛板にはどのような変化が起こるか。', '溶け出す', array['変化しない', '水素が発生する', '赤褐色のものが付着する'], '銅板と亜鉛板で電池を作った場合、亜鉛板が陰極になり亜鉛がZn²⁺ となって溶け出す。', null),
  ('sci_3_b4_093', '理科', 3, '電池', 2, 'うすい硫酸に亜鉛板と銅板で作った電池で銅板にはどのような変化が起こるか。', '水素が発生する', array['変化しない', '溶け出す', '赤褐色のものが付着する'], '銅板と亜鉛板で電池を作った場合、銅板が陽極となり水素が発生する。', null),
  ('sci_3_b4_094', '理科', 3, '電池', 1, '二次電池はどれか。', 'ニッケル水素電池', array['アルカリ電池', 'マンガン乾電池', '太陽電池'], '充電できる電池を二次電池と言い、鉛蓄電池やリチウムイオン電池、ニッケル水素電池などがある。', null),
  ('sci_3_b4_095', '理科', 3, '電池', 2, '水の電気分解の逆の化学変化を利用して電気エネルギーを取り出す装置を何というか。', '燃料電池', array['水素電池', '乾電池', '水電池'], '水の電気分解の逆の化学変化を利用して電気エネルギーを取り出す装置を燃料電池という。', null),
  ('sci_3_b4_096', '理科', 3, '電気分解とイオン', 2, '塩酸を電気分解したとき陰極から発生する気体の発生方法はどれか。', 'うすい硫酸に亜鉛をいれる。', array['二酸化マンガンに過酸化水素水をかける。', 'うすい塩酸に石灰石を入れる。', '塩化アンモニウムと水酸化カルシウムを混ぜて加熱する。'], '塩酸を電気分解すると陰極から水素が発生する。水素はうすい硫酸や塩酸に亜鉛などの金属を入れると発生する。二酸化マンガンに過酸化水素水では酸素、塩酸に石灰石では二酸化炭素、塩化アンモニウムと水酸化カルシウムの加熱ではアンモニアが発生する。', null),
  ('sci_3_b4_097', '理科', 3, '電気分解とイオン', 2, '塩酸を電気分解したとき陽極から発生する気体の性質はどれか。', '殺菌作用、漂白作用がある。', array['空気に比べて非常に軽い。', 'ものが燃えるのを助けるはたらきがある。', '空気中にたくさん存在する。'], '塩酸を電気分解したときに陽極から発生するのは塩素である。塩素は空気より重く、水によく溶け、刺激臭があり、黄緑色をしている。また、有毒で殺菌作用、漂白作用がある。', null),
  ('sci_3_b4_098', '理科', 3, '電気分解とイオン', 2, '塩化銅水溶液の青色はどのイオンによるものか。', 'Cu²⁺', array['H⁺', 'Cl⁻', 'OH⁻'], '塩化銅水溶液の青色は銅イオンによるものである。', null),
  ('sci_3_b4_099', '理科', 3, '電気分解とイオン', 2, '塩化銅水溶液を電気分解したとき気体が発生するのは何極か。', '陽極', array['陰極', '両方から発生する。', '両方共発生しない。'], '塩化銅水溶液を電気分解すると陰極には赤褐色の銅が付着し、陽極からは気体の塩素が発生する。', null),
  ('sci_3_b4_100', '理科', 3, 'イオンのしくみ', 3, '酸素原子には電子が8つある。陽子の数はいくつか。', '8', array['0', '4', '16'], '原子は電子、陽子、中性子からなりこれらの数は原子の種類によって異なるが1つの原子の中の電子と陽子は同数である。', null),
  ('sci_3_b4_101', '理科', 3, 'イオンのしくみ', 2, '電子と陽子の質量について正しいものはどれか。', '電子のほうが極めて小さい。', array['ほぼ等しい。', '陽子のほうが極めて小さい。', '決まっていない。'], '中性子と陽子の質量はほぼ等しいが、電子の質量はそれにくらべて極めて小さい。', null),
  ('sci_3_b4_102', '理科', 3, 'イオンのしくみ', 2, '原子核は何からできているか。', '陽子と中性子', array['電子と陽子', '電子と陽子と中性子', '原子と中性子'], '原子は原子核の周りに電子がある。原子核は陽子と中性子でできている。', null),
  ('sci_3_b4_103', '理科', 3, 'イオンのしくみ', 2, '陽イオンとは何か。', '原子が電子を失ったもの', array['原子が電子を受け取ったもの', '原子が陽子を失ったもの', '原子が陽子を受け取ったもの'], '原子は種類によって電子を失いやすいものと受け取りやすいものがあり、原子が電子を失ってプラスに帯電したものを陽イオンという。', null),
  ('sci_3_b4_104', '理科', 3, 'イオンのしくみ', 2, '陰イオンとは何か。', '原子が電子を受け取ったもの', array['原子が電子を失ったもの', '原子が陽子を失ったもの', '原子が陽子を受け取ったもの'], '原子は種類によって電子を失いやすいものと受け取りやすいものがあり、原子が電子を受け取ってマイナスに帯電したものを陰イオンという。', null),
  ('sci_3_b4_105', '理科', 3, 'イオンのしくみ', 1, '陽イオンはどれか。', 'ナトリウムイオン', array['塩化物イオン', '水酸化物イオン', '硫酸イオン'], 'それぞれイオン式で表すとナトリウムイオンNa⁺ 、塩化物イオンCl⁻ 、水酸化物イオンOH⁻ 、硫酸イオンSO₄²⁻ となる。', null),
  ('sci_3_b4_106', '理科', 3, 'イオンのしくみ', 1, '陰イオンはどれか。', '硝酸イオン', array['銅イオン', '水素イオン', 'アンモニウムイオン'], 'それぞれイオン式で表すと銅イオンCu²⁺ 、水素イオンH⁺ 、硝酸イオンNO₃⁻ 、アンモニウムイオンNH₄⁺', null),
  ('sci_3_b4_107', '理科', 3, 'イオンのしくみ', 2, '複数の原子がひとかたまりになって1つのイオンとしてはたらくものを何というか。', '多原子イオン', array['陽イオン', '陰イオン', '大イオン'], '複数の原子がひとかたまりでイオンとなっているのが多原子イオンである。OH⁻ 、NO₃⁻ 、SO₄²⁻ 、NH₄⁺ などがある。', null),
  ('sci_3_b4_108', '理科', 3, 'イオンのしくみ', 2, '水に溶けて陰イオンと陽イオンに別れることを何というか。', '電離', array['融解', '電解', '溶解'], '物質が水に溶けて陰イオンと陽イオンに別れることを電離という。', null),
  ('sci_3_b4_109', '理科', 3, 'イオンのしくみ', 2, '水に溶けて陰イオンと陽イオンに別れるような物質を何というか。', '電解質', array['イオン', '電離物質', '混合物'], '水に溶けると陰イオンと陽イオンに別れるような物質が電解質で塩化水素や食塩、水酸化ナトリウムなどがある。また水に溶けてもイオンに別れない物質が非電解質で砂糖やエタノールなどがある。', null),
  ('sci_3_b4_110', '理科', 3, 'イオンのしくみ', 2, 'HCl→H⁺+Cl⁻ のように物質がイオンにわかれる様子を表した式を何というか。', '電離式', array['化学式', '化学反応式', 'イオン反応式'], '物質が水に溶けてイオンに別れる電離の様子を表した式が電離式である。', null),
  ('sci_3_b4_111', '理科', 3, 'イオンのしくみ', 2, 'H⁺ やOH⁻ のようにイオンを表す記号を何というか。', 'イオン式', array['元素記号', '電解式', '化学式'], 'イオンを表す記号がイオン式で、陽イオンは元素記号の右上に+をつける。陰イオンは元素記号の右上に−をつける。', null),
  ('sci_3_b4_112', '理科', 3, '運動のようす', 2, 'A等速直線運動 B静止 C速さが一定の割合で大きくなる D速さが一定の割合で小さくなる A〜Dのうち物体にはたらく力がつり合っているのはどれか。', 'AとB', array['A', 'B', 'D'], '物体は力がはたらかないか、はたらいていてもつり合っているとき、静止しているものは静止し続け、運動しているものは等速直線運動を続ける', null),
  ('sci_3_b4_113', '理科', 3, '運動のようす', 2, '物体は力がはたらかないか、はたらいていてもつり合っているとき、静止しているものは静止し続け、運動しているものは等速直線運動を続ける。 この法則を何というか。', '慣性の法則', array['つり合いの法則', 'エネルギー保存の法則', '仕事の原理'], '物体は力がはたらかないか、はたらいていてもつり合っているとき、静止しているものは静止し続け、運動しているものは等速直線運動を続ける。これを慣性の法則といい、物体の持つこの性質を慣性という。', null),
  ('sci_3_b4_114', '理科', 3, '運動のようす', 2, '力は常に2つの物体の間で対になってはたらきあう。その一対の力は大きさが等しく、反対向きで同一直線上である。この法則を何というか。', '作用反作用の法則', array['つり合いの法則', 'エネルギー保存の法則', '仕事の原理'], '「力は常に2つの物体の間で対になってはたらきあう。その一対の力は大きさが等しく、反対向きで同一直線上である。」これが作用反作用の法則である。', null),
  ('sci_3_b4_115', '理科', 3, '運動のようす', 2, '物体がある時間の間、同じ速さで動き続けたと仮定して、「移動距離÷かかった時間」という計算で求められる速さのことを何というか。', '平均の速さ', array['瞬間の速さ', '移動の速さ', '運動の速さ'], '物体がある時間の間、一定の速さで動き続けたと考えた場合、移動した距離を移動にかかった時間で割った速さのことを「平均の速さ」という。極短い時間での平均の速さが「瞬間の速さ」である。', null),
  ('sci_3_b4_116', '理科', 3, '運動のようす', 2, '物体の運動の様子を表すには（　　）を正確に示さなければならない。', '速さと向き', array['速さと力', '時間と距離', '力の大きさと向き'], '運動の様子を表すには速さだけでなく、運動の向きも示す必要がある。', null),
  ('sci_3_b4_117', '理科', 3, '運動のようす', 2, '一定の時間間隔でテープに点が打たれる装置を何というか。', '記録タイマー', array['メトロノーム', 'スピートメーター', 'ストロボ'], '記録タイマーには一定の時間間隔でテープに点が打たれる。東日本では1秒間に50回、西日本では1秒間に60回である。', null),
  ('sci_3_b4_118', '理科', 3, '運動のようす', 3, '90kmの距離を2時間で移動したときの速さは何m/sか。', '12.5m/s', array['45m/s', '0.75m/s', '90m/s'], '90kmは90000m、 2時間は 2×60×60=7200なので90000÷7200=12.5', null),
  ('sci_3_b4_119', '理科', 3, '運動のようす', 2, 'A地点からB地点を通ってC地点まで全部で120kmある。AからBまで時速40kmで0.5時間かかり、BからCまで時速50kmで2時間かかった。AからBを通ってCまで行ったときの平均速さ何km/hか。', '48km/h', array['42km/h', '45km/h', '0.8km/h'], '平均の速さ=移動距離÷かかった時間なので 120÷2.5=48', null),
  ('sci_3_b4_120', '理科', 3, '運動のようす', 2, '物体が等速直線運動をするときの力はどれか。', '力は加わらない', array['常に一定の大きさの力', '一定の割合で大きくなる力', '一定の割合で小さくなる力'], '物体に力が加わらないか、または加わっている力がつり合っているとき、その物体は等速直線運動をする。', null),
  ('sci_3_b4_121', '理科', 3, '仕事とエネルギー', 2, 'エネルギーとは何か。', '仕事をする能力', array['物体が持つ固有の値', '継続的に発生する力', '他の物体に対してはたらく力'], 'ある物体が他の物体に対して仕事ができる状態に有る場合、その物体はエネルギーを持っているという。エネルギーの単位は仕事と同じJ(ジュール)である。', null),
  ('sci_3_b4_122', '理科', 3, '仕事とエネルギー', 2, '物体の高さと、物体にはたらく重力にそれぞれ比例するエネルギーを何というか。', '位置エネルギー', array['運動エネルギー', '高エネルギー', '化学エネルギー'], '高いところにある物体は、落下させると他の物体に対して仕事をすることができる。この高いところにある物体の持つエネルギーを位置エネルギーと呼ぶ。位置エネルギーは高さと重力にそれぞれ比例する。', null),
  ('sci_3_b4_123', '理科', 3, '仕事とエネルギー', 2, '物体の質量に比例し、物体の（　　）が大きいほど大きくなるエネルギーを運動エネルギーという。', '速さ', array['力', '密度', '抵抗'], '運動している物体は他の物体に衝突することで仕事をすることができる。この運動する物体の持つエネルギーを運動エネルギーと呼ぶ。運動エネルギーは物体の質量と、速さの2乗にそれぞれ比例する。', null),
  ('sci_3_b4_124', '理科', 3, '仕事とエネルギー', 2, '物体を自由落下させた場合、高さが低くなると位置エネルギーは小さくなる。この減ったエネルギーはどうなったのか。', '運動エネルギーに変わる', array['消えた', '化学エネルギーとして物体に蓄えれれる', '他の物体の位置エネルギーに変わる'], '落下運動は一定の力(重力)がかかり続ける運動なので、落下するときは速さが0でも徐々に速さが速くなる。つまり、落下して高さが低くなるとその分、速さが速くなる。エネルギーでみると位置エネルギーが運動エネルギーに変わっているといえる。', null),
  ('sci_3_b4_125', '理科', 3, '仕事とエネルギー', 2, '力学的エネルギーとは何か。', '位置エネルギーと運動エネルギーの和', array['すべてのエネルギーの和', 'バネを縮めたときのエネルギー', '熱エネルギーと化学エネルギーの和'], '位置エネルギーと運動エネルギーの和を力学的エネルギーという。', null),
  ('sci_3_b4_126', '理科', 3, '仕事とエネルギー', 3, '力学的エネルギー保存の法則はどれか。', '摩擦や空気抵抗がなければ位置エネルギーと運動エネルギーの和は一定である。', array['エネルギーは様々な形に変化するが、その総和は一定である。', '位置エネルギーが運動エネルギーに変わるとき、摩擦や空気の抵抗によって熱エネルギーも出る。', 'エネルギーを他のエネルギーに変換する場合、目的とするエネルギー以外にほとんどの場合熱エネルギーになってしまう。'], '落下運動や振り子の運動などで、物体の高さが低くなると速さが大きくなる。このとき摩擦や空気の抵抗がなければ位置エネルギーが減った分だけ運動エネルギーが増える。つまり位置エネルギーと運動エネルギーの和である力学的エネルギーは一定に保たれる。これを力学的エネルギー保存の法則(または力学的エネルギーの保存)という。', null),
  ('sci_3_b4_127', '理科', 3, 'エネルギーの移り変わり', 2, '伸びたゴムや縮んだばねなど変形した物体の持つエネルギーを何というか。', '弾性エネルギー', array['力学的エネルギー', '熱エネルギー', '化学エネルギー'], '変形した物体がもとに戻ろうとする力(弾性力)によるエネルギーが弾性エネルギーである。', null),
  ('sci_3_b4_128', '理科', 3, 'エネルギーの移り変わり', 2, '光合成は何エネルギーを何エネルギーに変換しているのか。', '光エネルギーを化学エネルギー', array['化学エネルギーを熱エネルギー', '光エネルギーを熱エネルギー', '光エネルギーを電気エネルギー'], '光合成では太陽の光エネルギーをつかって、水と二酸化炭素から大きな化学エネルギーを持つ有機物を合成している。', null),
  ('sci_3_b4_129', '理科', 3, 'エネルギーの移り変わり', 2, '化学エネルギーを電気エネルギーに変換する装置を何というか。', '電池', array['タービン', '発電機', 'ソーラーパネル'], '化学変化で取り出すことができるのが化学エネルギーである。電池は化学変化を利用して化学エネルギーエオ電気エネルギーに変換している。', null),
  ('sci_3_b4_130', '理科', 3, 'エネルギーの移り変わり', 2, '水力発電所では何エネルギーを電気エネルギーに変えているのか。', '位置エネルギー', array['化学ネルギー', '光エネルギー', '核エネルギー'], '水力発電は高いところから水を落としてタービンを回し、そこにつながった発電機が回って電気エネルギーを作り出す。', null),
  ('sci_3_b4_131', '理科', 3, 'エネルギーの移り変わり', 2, 'エネルギーが移り変わっても、その総量は変化せず一定に保たれる。ことを何というか。', 'エネルギー保存の法則', array['仕事の原理', '運動の法則', '作用反作用の法則'], 'エネルギーは様々な形に変換できるが、その変換の前後でエネルギーの総量は変化せず一定に保たれる。これをエネルギー保存の法則(またはエネルギーの保存)という。', null),
  ('sci_3_b4_132', '理科', 3, 'エネルギーの移り変わり', 2, 'もとのエネルギーから目的のエネルギーに何%変換できるかを（　　）という。', '変換効率', array['エネルギーの保存', '仕事率', 'エネルギーの損失'], '投入されたエネルギーに対して利用できるエネルギーの割合を変換効率という。', null),
  ('sci_3_b4_133', '理科', 3, 'エネルギーの移り変わり', 2, '変換効率のもっとも良い照明器具はどれか。', '発光ダイオード', array['ろうそく', '蛍光灯', '白熱電球'], '発光ダイオード(LED)は他の照明器具に比べてエネルギーの変換効率が良い。それでも電気エネルギーの7割以上が熱エネルギーに変わってしまう。', null),
  ('sci_3_b4_134', '理科', 3, 'エネルギーの移り変わり', 2, '熱には3つの伝わり方がある。間違っているのはどれか。', '移動', array['伝導', '対流', '放射'], '熱の伝わり方は伝導(熱伝導)、対流、放射(熱放射)の3つである。', null),
  ('sci_3_b4_135', '理科', 3, 'エネルギーの移り変わり', 2, '温度の異なる物体が（　　）とき高温のほうから低温のほうに熱が伝わるのが熱伝導である。', '接している', array['離れている', '動いている', '気体の'], '温度のことなる物質が接すると、接したところで高温の方から低音の方へエネルギーが移っていく。', null),
  ('sci_3_b4_136', '理科', 3, 'エネルギーの移り変わり', 2, '場所によって温度がことなる液体や気体が（　　）して熱が運ばれる現象が対流である。', '流動', array['分離', '状態変化', '化学変化'], '液体や気体で場所によって温度がことなると、温度の高い部分は密度が低いので上に移動し、温度が低い部分は下に移動する。', null),
  ('sci_3_b4_137', '理科', 3, 'エネルギーの移り変わり', 2, '高温の物体が（　　）を出して空間をへだてて離れたところまで熱が伝わる現象を熱放射という。', '光や赤外線', array['エネルギーの大きな粒子', '電気', '空気の流れ'], '高温の物体は光や赤外線を出している。この光や赤外線はエネルギーを持っているので、それがあたった物体はエネルギーを受け取って温度が上昇する。太陽の光があたると暖かくなるのはこの例である。', null),
  ('sci_3_b4_138', '理科', 3, '力の合成と分解', 2, '合力を求めることを何というか。', '力の合成', array['力の重複', '力の合計', '力のつりあい'], '物体にはたらく2つの力を、それらと同じはたらきの1つの力におきかえることを力の合成という。', null),
  ('sci_3_b4_139', '理科', 3, '力の合成と分解', 2, '物体にはたらく力がつり合っているとき、それらの合力は（　　）になる。', '0', array['倍', '半分', '同じ'], '物体に力がはたらいていて、それらがつり合っているときは物体に力がはたらいていないのと同じ状態である。', null),
  ('sci_3_b4_140', '理科', 3, '力の合成と分解', 3, '力Aと力Bは一直線上にあり、向きが同じである。力Aの大きさが5N、力Bの大きさが8Nのとき、AとBの合力の大きさはいくつか。', '13N', array['3N', '5N', '8N'], '力が一直線上にあり、向きが同じなら、合力の大きさは2つの力の和になる。', null),
  ('sci_3_b4_141', '理科', 3, '力の合成と分解', 3, '力Aと力Bは一直線上にあり、向きが逆である。力Aの大きさが2N、 力Bの大きさが7NのときAとBの合力の大きさはいくつか。', '5N', array['2N', '7N', '9N'], '力が一直線上にあり、向きが逆なら、合力の大きさは2つの力の差になる。', null),
  ('sci_3_b4_142', '理科', 3, '力の合成と分解', 2, '一直線上にない2力を合成した合力はどれか。', '2力を2辺とする平行四辺形の対角線。', array['2力の大きさの和。', '2力の大きさの差。', '2力の大きさの積。'], '一直線上にない2力の合力は、その2力を2辺とする平行四辺形の対角線で表される。これを力の合成という。', null),
  ('sci_3_b4_143', '理科', 3, '力の合成と分解', 2, '力を分解して求めた力は、もとの力の（　　）という。', '分力', array['重力', '子力', '小力'], '力Aと力Bの合力を力Fとすると力Aと力Bは力Fの分力である', null),
  ('sci_3_b4_144', '理科', 3, '力の合成と分解', 2, '力を分解する方法はどれか。', 'もとの力を対角線とする平行四辺形のとなりあう2辺が分力になる。', array['もとの力を対角線とする平行線の対辺が分力になる。', 'もとの力を1辺とする平行四辺形の2つの対角線が分力になる。', 'もとの力を1辺とする三角形の底辺と高さが分力になる。'], 'もとの力を対角線とする平行四辺形を作るり、その平行四辺形のとなりあう2辺が分力になる。分解する方向によって何通りにも分解できる。', null),
  ('sci_3_b4_145', '理科', 3, '力の合成と分解', 2, '斜面が物体におよぼす垂直抗力とつり合っているのはどの力か。', '斜面に垂直な重力の分力', array['物体にはたらく重力', '斜面に平行な重力の分力', '斜面の摩擦力'], '斜面に置いた物体にかかる重力は斜面に平行な方向と、斜面に垂直な方向に分解して考える。斜面に垂直な分力は垂直抗力とつり合っている。', null),
  ('sci_3_b4_146', '理科', 3, '仕事と仕事率', 1, '仕事の単位は何か。', 'J(ジュール)', array['N(ニュートン)', 'W(ワット)', 'g(グラム)'], '仕事の単位はJ(ジュール)である。J(ジュール)はエネルギーの単位でもあるので熱量などにも使われる。', null),
  ('sci_3_b4_147', '理科', 3, '仕事と仕事率', 2, '仕事が求められる式はどれか。', '力×距離', array['力÷距離', '力×秒', '力÷秒'], '「仕事 = 力×力の向きに動いた距離」で求めることができる。', null),
  ('sci_3_b4_148', '理科', 3, '仕事と仕事率', 2, '「同じ仕事をする場合、道具を使っても使わなくても仕事の量は変わらない。」これを何というか。', '仕事の原理', array['仕事普遍の法則', 'エネルギー保存の法則', '慣性の法則'], '動滑車やてこ、斜面などの道具をつかうと力を加える距離を長くして必要な力を小さくすることができる。', null),
  ('sci_3_b4_149', '理科', 3, '仕事と仕事率', 1, '仕事率の単位は何か。', 'W(ワット)', array['N(ニュートン)', 'J(ジュール)', 'g(グラム)'], '仕事率の単位はW(ワット)である。W(ワット)は電力の単位でもある。', null),
  ('sci_3_b4_150', '理科', 3, '仕事と仕事率', 2, '仕事率が求められる式はどれか。', '仕事÷秒', array['仕事÷力', '仕事÷距離', '仕事×時間'], '仕事率は仕事の能率を表し、「仕事率 = 仕事÷時間(s)」で求められる。', null),
  ('sci_3_b4_151', '理科', 3, '仕事と仕事率', 1, '仕事の単位はどれか。', 'J', array['N', 'W', 'kg'], '使徒との単位はJ(ジュール)を使う。N(ニュートン)は力の単位、W(ワット)は仕事率、kg(キログラム)は質量の単位である。', null),
  ('sci_3_b4_152', '理科', 3, '仕事と仕事率', 1, '仕事を求める式はどれか。', '仕事=力×距離', array['仕事 = 力÷面積', '仕事=力×速さ', '仕事=質量×速さ'], '仕事 = 力×力の向きに移動させた距離である。', null),
  ('sci_3_b4_153', '理科', 3, '仕事と仕事率', 2, '「道具を使っても使わなくても仕事の大きさは変わらない」これを（　　）という。', '仕事の原理', array['エネルギー保存の法則', '作用反作用の法則', '慣性の法則'], '同じ仕事をする場合、滑車やてこなどの道具を使うと力の向きに動かす距離は長くなるが、小さな力で動かすことができる。', null),
  ('sci_3_b4_154', '理科', 3, '仕事と仕事率', 2, '仕事率を求める式はどれか。', '仕事率 = 仕事 ÷ 時間', array['仕事率 = 仕事 × 距離', '仕事率 = 仕事×時間', '仕事率=仕事÷距離'], '仕事率は仕事の能率を表している。 仕事率 = 仕事 ÷ 仕事にかかった時間 2年の範囲の電力(W)は電気による仕事率である。', null),
  ('sci_3_b4_155', '理科', 3, '仕事と仕事率', 3, '摩擦のある床に置いてある物体に、20Nの力を加えて一定の速さで4m移動させた。このときの仕事は何Jか。', '80J', array['5J', '20J', '0.2J'], '仕事(W)=力(N)×力の方向に移動した距離(m)なので20×', null),
  ('sci_3_b4_156', '理科', 3, '仕事と仕事率', 3, '600gの物体を真上に20cmゆっくりと持ち上げた。このときの仕事は何Jか。', '1.2J', array['12000J', '30J', '120J'], '600gにかかる重力は6N、 20cmは0.2mなので 6×0.2=1.2', null),
  ('sci_3_b4_157', '理科', 3, '仕事と仕事率', 3, '摩擦のある床に置いてある物体に、150Nの力を加えて一定の速さで4m移動させた。このときにかかった時間が3秒だった。仕事率は何Wか。', '200W', array['600W', '150W', '1800W'], '150Nで4m移動したので仕事は150×4=600 かかった時間が3秒なので仕事率 = 仕事÷時間より 600÷3=200', null),
  ('sci_3_b4_158', '理科', 3, '仕事と仕事率', 3, '2000gの物体を真上に10cm/sの一定の速さで持ち上げた。このときの仕事率は何Wか。', '2W', array['0.2W', '20W', '200W'], '2000gにかかる重力は20N、10cm/sは0.1m/sなので1秒間に移動する距離は0.1m つまり1秒間にする仕事は20×0.1=2', null),
  ('sci_3_b4_159', '理科', 3, '水圧と浮力', 2, '密度が（　　）g/cm³より小さい物体は水に浮く。', '1', array['0.5', '10', '1013'], '水の密度1g/cm³よりも物体の密度が小さいと、その物体は水に浮く。', null),
  ('sci_3_b4_160', '理科', 3, '遺伝の規則性', 2, 'DNAについて間違っているものはどれか。', '多細胞生物だけが持っている。', array['デオキシリボ核酸', '遺伝子の本体を構成する物質', '細胞の核の中にある。'], 'DNAとは、遺伝子を構成する物質のデオキシリボ核酸の略称である。ほとんどの単細胞生物と多細胞生物が持っている。', null),
  ('sci_3_b4_161', '理科', 3, '遺伝の規則性', 2, '対立形質の純系どうしをかけあわせたときに子に現れる形質を何というか。', '顕性形質', array['子現形質', '潜性形質', '中間形質'], '対立形質の純系どうしをかけあわせたときに子に現れる形質を顕性形質、現れない形質を潜性形質という。', null),
  ('sci_3_b4_162', '理科', 3, '遺伝の規則性', 2, '対立形質の純系どうしかけあわせてできた子には現れず、子を自家受精させてできた孫に現れる形質を何というか。', '潜性形質', array['孫現形質', '顕性形質', '中間形質'], '対立形質の純系どうしを掛けあわせてできる子の遺伝子はAaとなり、子を自家受精させると孫の遺伝子はAA、Aa、Aa、aaとなるので潜性形質も現れる。', null),
  ('sci_3_b4_163', '理科', 3, '遺伝の規則性', 2, '減数分裂で生殖細胞が作られるとき、対になっている遺伝子が分かれて別々の生殖細胞に入る。この法則は何か。', '分離の法則', array['優性の法則', '独立の法則', '減数分裂の法則'], '減数分裂で生殖細胞が作られるときに染色体数が半分になる。このとき対になっている遺伝子が別れて別々の生殖細胞に入る。体細胞Aaからできる生殖細胞はAとaである。', null),
  ('sci_3_b4_164', '理科', 3, '遺伝の規則性', 2, '対立形質を持つ純系どうしをかけあわせた場合、子には一方の形質だけが現れる。 この法則は何か。', '優性の法則', array['分離の法則', '独立の法則', '減数分裂の法則'], '対立形質を持つ純系どうしをかけあわせた場合、子の遺伝子はAaとなり、このとき子には一方の形質だけが現れる。この法則を優性の法則といい、このとき現れる形質を顕性形質という。', null),
  ('sci_3_b4_165', '理科', 3, '酸・アルカリ', 2, '酸性の水溶液について正しいのはどれか。', '青色リトマス紙を赤色に変える。', array['赤色リトマス紙を青色に変える。', 'リトマス紙を変化させない。', 'BTB溶液を青色に変える。'], '酸性の水溶液は青色リトマス紙を赤色に変え、アルカリ性の水溶液は赤色リトマス紙を青色に変える。', null),
  ('sci_3_b4_166', '理科', 3, '酸・アルカリ', 2, 'pH試験紙が黄色になったときの水溶液は何性か。', '酸性', array['アルカリ性', '中性', '強いアルカリ性'], 'pH試験紙は酸性で黄色〜赤色になりアルカリ性で青色になる。', null),
  ('sci_3_b4_167', '理科', 3, '酸・アルカリ', 2, 'pHが7より大きい水溶液は何性か。', 'アルカリ性', array['酸性', '中性', '強い酸性'], 'pHは酸性やアルカリ性の強さを表す0〜14の数値で、7のとき中性である。7より大きいとアルカリ性で数値が大きいほど強いアルカリ性になる。7より小さいと酸性で数値が小さいほど強い酸性になる。', null),
  ('sci_3_b4_168', '理科', 3, '電池', 2, '亜鉛とマグネシウムで電池を作ったとしたら陽極になるのはどちらか。', '亜鉛', array['マグネシウム', 'どちらともいえない', '両方が陽極になる'], '亜鉛とマグネシウムではマグネシウムのほうが陽イオンになりやすい性質なのでマグネシウムが陰極で亜鉛が陽極になる。', null),
  ('sci_3_b4_169', '理科', 3, '電気分解とイオン', 2, '塩酸を電気分解したとき集まる気体の体積はどちらの極のほうが多いか。', '陰極', array['陽極', '両方同じ', '電流の大きさによって変わる'], '塩酸を電気分解したときに発生する気体は両極とも同じ体積だが、水素は水に溶けにくく塩素は水に溶けやすいので集まる体積は水素のほうが多くなる。', null),
  ('sci_3_b4_170', '理科', 3, 'イオンのしくみ', 2, '陽子のもつ電気は何か。', '+', array['−', '電気を帯びていない。', '+と−の両方'], '原子は電子、陽子、中性子からなり、電子は−の電気を、陽子は+の電気を帯びている。中性子は電気を帯びていない。', null),
  ('sci_3_b4_171', '理科', 3, 'イオンのしくみ', 2, '原子全体では何の電気を帯びているか。', '電気を帯びていない。', array['+', '−', '+と−の両方'], '電子1つの持つ−の電気の量と陽子1つの持つ+の電気の量は等しい。また1つの原子の中に電子と陽子は同数あるので原子全体では電気を帯びていない。', null),
  ('sci_3_b4_172', '理科', 3, 'イオンのしくみ', 2, 'イオンとは何か。', '原子が電気を帯びたもの', array['原子が水に溶けたもの', '原子が化学変化したもの', '原子がいくつか結びついたもの'], '通常原子は電気的に中性だが、その原子がプラスに帯電すると陽イオン、マイナスに帯電すると陰イオンとなる。', null),
  ('sci_3_b4_173', '理科', 3, '運動のようす', 2, '止まっているバスが急発進したら、乗客はどうなるか。', 'うしろに傾く', array['前に傾く', '何の変化もない', '左右に揺れる'], '物体は力がはたらかないか、はたらいていてもつり合っているとき、静止しているものは静止し続けるので、乗客は静止し続けようとしてうしろに傾く', null),
  ('sci_3_b4_174', '理科', 3, '水圧と浮力', 2, '物体にはたらく水圧は、水深が深くなるとどうなるか。', '大きくなる', array['変わらない', '小さくなる', '容器の形によって変わる'], '水圧とは、水の重さによって生じる圧力である。水深が深くなるほど上に乗る水の量が増えるので、水圧は水深に比例して大きくなる。', null),
  ('sci_3_b4_175', '理科', 3, '水圧と浮力', 2, '水中部分の体積が変化しない場合、物体にはたらく浮力は水深が深くなるとどうなるか。', '変わらない', array['大きくなる', '小さくなる', '物体の重さによって変わる'], '水中の体積が同じなら、浮力は水深とかかわりなく一定になる。', null),
  ('sci_3_b4_176', '理科', 3, '水圧と浮力', 2, '浮力は水中部分の体積が大きいとどうなるか。', '大きくなる', array['変わらない', '小さくなる', '物体の密度によって決まる'], '浮力は水中部分の体積に比例して大きくなる。', null),
  ('sci_3_b4_177', '理科', 3, '水圧と浮力', 2, '上空と地表付近ではどちらの気圧が高いか。', '地表付近', array['同じ', '上空', '天気によって入れかわる'], '気圧は、空気の重さによって生じる圧力である。上空ほど上に乗る空気が少ないので上空ほど気圧は小さい。', null),
  ('sci_3_b4_178', '理科', 3, '運動のようす', 2, '運動の向きに一定の力がはたらき続けると物体の速さは（　　）。', '一定の割合で大きくなっていく', array['一定のまま変化しない', '小さくなっていく', 'はじめは大きくなり、やがて一定になる'], '物体に力を加えると加えた力の大きさに応じて物体の速さが変化する。物体に運動と同じ向きに一定の力が加わり続けると、速さは一定の割合で大きくなる。', null),
  ('sci_3_b4_179', '理科', 3, '運動のようす', 2, '斜面の運動で、斜面の角度が大きくなると（　　）が大きくなる。', '速さが変化する割合', array['垂直抗力', '物体にかかる重力', '物体の質量'], '斜面の角度を大きくすると、重力の斜面に平行な分力が大きくなるので、速さが変化する割合が大きくなる。', null)
